window.BASIC_DATA = {"source":"docs/BASIC_REFERENCE.md","keywords":{"ABS":"function","ADC":"function","AND":"operator","ASC":"function","ATN":"function","AUTO":"statement","BEEP":"statement","BLOAD":"statement","BSAVE":"statement","BYE":"statement","CALL":"statement","CDBL":"function","CHAIN":"statement","CHDIR":"statement","CHR$":"function","CINT":"function","CLEAR":"statement","CLOSE":"statement","CLS":"statement","COLOR":"statement","COM":"statement","COMMON":"statement","CONFIG":"statement","CONT":"statement","COS":"function","CSNG":"function","CSRLIN":"function","CVD":"function","CVI":"function","CVS":"function","DATA":"statement","DATE$":"statement","DEF":"statement","FN":"statement","SEG":"statement","DEFDBL":"statement","DEFINT":"statement","DEFSNG":"statement","DEFSTR":"statement","DELETE":"statement","DIM":"statement","DIR$":"function","EDIT":"statement","END":"statement","ENVIRON":"statement","ENVIRON$":"function","EOF":"function","EQV":"operator","ERASE":"statement","ERDEV":"function","ERL":"function","ERR":"function","ERROR":"statement","EXIT":"statement","FOR":"statement","EXP":"function","EXTERR":"function","FIELD":"statement","FILES":"statement","FIX":"function","FORMAT":"statement","FRE":"function","FREEFILE":"function","FUNCTION":"statement","GET":"statement","GOSUB":"statement","GOTO":"statement","HEX$":"function","I2C":"statement","I2CREAD":"function","I2CREAD$":"function","IF":"statement","IMP":"operator","INCLUDE":"statement","INKEY$":"function","INPUT":"statement","INPUT$":"function","INSTR":"function","INT":"function","KEY":"statement","KILL":"statement","LCASE$":"function","LEFT$":"function","LEN":"function","LET":"statement","LINE":"statement","LIST":"statement","LLIST":"statement","LOAD":"statement","LOC":"function","LOCATE":"statement","LOF":"function","LOG":"function","LPRINT":"statement","LSET":"statement","MERGE":"statement","MID$":"statement","MKD$":"function","MKDIR":"statement","MKI$":"function","MKS$":"function","MQTT":"statement","NAME":"statement","NEOPIXEL":"statement","NEW":"statement","NEXT":"statement","NOT":"operator","NTP":"statement","NUMBERS":"statement","OCT$":"function","ON":"statement","PLAY":"statement","TIMER":"statement","OPEN":"statement","OPTION":"statement","BASE":"statement","OR":"operator","PAUSE":"statement","PEEK":"function","PIN":"statement","PINMODE":"statement","PINS":"statement","POKE":"statement","POS":"function","PRINT":"statement","USING":"statement","PUT":"statement","PWM":"statement","RANDOMIZE":"statement","READ":"statement","REM":"statement","RENUM":"statement","RESET":"statement","RESTORE":"statement","RESUME":"statement","RETURN":"statement","RIGHT$":"function","RMDIR":"statement","RND":"function","RSET":"statement","RUN":"statement","SAVE":"statement","SCREEN":"function","SERVO":"statement","SGN":"function","SHARED":"statement","SIN":"function","SOUND":"statement","SPACE$":"function","SPC":"function","SPI":"statement","SPI$":"function","SQR":"function","STOP":"statement","STR$":"function","STRING$":"function","SUB":"statement","SWAP":"statement","SYSTEM":"statement","TAB":"function","TAN":"function","TEMP":"function","TIME$":"statement","TROFF":"statement","TRON":"statement","UCASE$":"function","VAL":"function","VIEW":"statement","WATCHDOG":"statement","WDRESET":"function","WEND":"statement","WHILE":"statement","WIDTH":"statement","WIFI":"statement","WRITE":"statement","XOR":"operator","XRECV":"statement","XSEND":"statement","MOD":"operator","THEN":"statement","ELSE":"statement","TO":"statement","STEP":"statement","AS":"statement","APPEND":"statement","OUTPUT":"statement","RANDOM":"statement","OFF":"statement","ALL":"statement","ACCESS":"statement","LOCK":"statement","CONNECT":"statement","DISCONNECT":"statement","PUBLISH":"statement","SUBSCRIBE":"statement","UNSUBSCRIBE":"statement","PULLUP":"statement","PULLDOWN":"statement","SCAN":"statement","SHOW":"statement","FILL":"statement","BRIGHT":"statement","CLOCK":"statement","FEED":"statement","NOSTOP":"statement"},"entries":[{"title":"+ - * / ^","id":"ref--","kind":"Operator","body":"*Operator* · `a + b, a - b, a * b, a / b, a ^ b`\n\nAdd, subtract, multiply, divide, power. `+` also joins strings. `-x` negates. Calculations are in double precision.\n\n- Errors: `Division by zero` (11), `Overflow` (6), `Type mismatch` (13) mixing strings and numbers.\n\nExample:\n\n```\nPRINT 2 ^ 10; 7 / 2; \"AB\" + \"CD\"\n```\n\nShows:\n\n```\n 1024  3.5 ABCD\n```\n\nSee also: [\\ and MOD](#ref-and-mod)"},{"title":"= <> < > <= >=","id":"ref-op","kind":"Operator","body":"*Operator* · `a = b, a <> b, a < b, a > b, a <= b, a >= b`\n\nComparisons, of numbers or of strings (by character codes): -1 for true, 0 for false.\n\nExample:\n\n```\nPRINT 3 > 2; \"A\" < \"B\"; 1 = 2\n```\n\nShows:\n\n```\n-1 -1  0\n```\n\nSee also: [IF](#ref-if), [AND](#ref-and)"},{"title":"?","id":"ref-op-1","kind":"Statement","body":"*Statement* · `? items`\n\nShort for PRINT.\n\nExample:\n\n```\n? 1 + 1\n```\n\nShows:\n\n```\n 2\n```\n\nSee also: [PRINT](#ref-print)"},{"title":"ABS","id":"ref-abs","kind":"Function","body":"*Function* · `ABS(x)`\n\nThe absolute value of `x` (`x` without its sign).\n\nExample:\n\n```\nPRINT ABS(-3.5)\n```\n\nShows:\n\n```\n 3.5\n```\n\nSee also: [SGN](#ref-sgn)"},{"title":"ADC","id":"ref-adc","kind":"Function","body":"*Function* · `ADC(pin)`\n\nReads an analog input: 0-4095 for 0-3.3 V. GP26-29 on the Pico and Pico 2 (GP29 is VSYS / 3), GP40-46 on the Pico Plus 2.\n\n- Errors: `Illegal function call` (5) for a pin without one.\n\nExample:\n\n```\nPRINT ADC(26) * 3.3 / 4095\n```\n\nShows:\n\n```\n 1.65040293\n```\n\nSee also: [TEMP](#ref-temp), [PIN](#ref-pin)"},{"title":"AND","id":"ref-and","kind":"Operator","body":"*Operator* · `a AND b`\n\nBitwise AND of two integers: true (-1) only if both are. Also masks bits: `X AND 15`.\n\nExample:\n\n```\nPRINT 12 AND 10; (1 < 2) AND (2 < 3)\n```\n\nShows:\n\n```\n 8 -1\n```\n\nSee also: [OR](#ref-or), [NOT](#ref-not)"},{"title":"ASC","id":"ref-asc","kind":"Function","body":"*Function* · `ASC(s$)`\n\nThe code (0-255) of the first character of `s$`.\n\n- Errors: `Illegal function call` (5) for \"\".\n\nExample:\n\n```\nPRINT ASC(\"A\")\n```\n\nShows:\n\n```\n 65\n```\n\nSee also: [CHR$](#ref-chr)"},{"title":"ATN","id":"ref-atn","kind":"Function","body":"*Function* · `ATN(x)`\n\nThe arctangent of `x`, in radians (-π/2 to π/2).\n\nExample:\n\n```\nPRINT ATN(1) * 4\n```\n\nShows:\n\n```\n 3.14159265\n```\n\nSee also: [TAN](#ref-tan), [SIN](#ref-sin), [COS](#ref-cos)"},{"title":"AUTO","id":"ref-auto","kind":"Command","body":"*Command* · `AUTO [start][, step]`\n\nNumbers the lines you type: each new line starts with the next number, so you just type the statement.\n\n- `start` and `step` default to 10 and 10.\n- A `*` after the number means that line already exists: Enter keeps it as it is.\n- An empty line where no line exists, or Ctrl-C, stops it.\n\nExample:\n\n```\nAUTO 100, 5\n```\n\nShows:\n\n```\n100 \n```\n\nSee also: [RENUM](#ref-renum), [DELETE](#ref-delete)"},{"title":"BEEP","id":"ref-beep","kind":"Statement","body":"*Statement* · `BEEP`\n\nA short beep: 800 Hz for a quarter of a second, on the speaker pin (GP18, the Maker Pi Pico's buzzer).\n\nExample:\n\n```\nBEEP\n```\n\nSee also: [SOUND](#ref-sound), [PLAY](#ref-play)"},{"title":"BLOAD","id":"ref-bload","kind":"Statement","body":"*Statement* · `BLOAD file$[, offset]`\n\nLoads a file saved by BSAVE (a 7-byte header) into the emulated memory (DEF SEG).\n\nSee also: [BSAVE](#ref-bsave), [DEF SEG](#ref-def-seg)"},{"title":"BSAVE","id":"ref-bsave","kind":"Statement","body":"*Statement* · `BSAVE file$, offset, length`\n\nSaves `length` bytes of the emulated memory (DEF SEG) to a file.\n\nSee also: [BLOAD](#ref-bload)"},{"title":"BYE","id":"ref-bye","kind":"Command","body":"*Command* · `BYE`\n\nThe same as SYSTEM.\n\nSee also: [SYSTEM](#ref-system)"},{"title":"CALL","id":"ref-call","kind":"Statement","body":"*Statement* · `CALL name[(arg[, arg...])]`\n\nCalls a SUB; the same as `name arg, arg`.\n\nExample:\n\n```\nCALL SHOW(\"HI \", 2)\n```\n\nShows:\n\n```\nHI HI\n```\n\nSee also: [SUB](#ref-sub)"},{"title":"CDBL","id":"ref-cdbl","kind":"Function","body":"*Function* · `CDBL(x)`\n\n`x` as a double-precision number.\n\nExample:\n\n```\nPRINT CDBL(1) / 3\n```\n\nShows:\n\n```\n .333333333\n```\n\nSee also: [CSNG](#ref-csng), [CINT](#ref-cint)"},{"title":"CHAIN","id":"ref-chain","kind":"Statement","body":"*Statement* · `CHAIN [MERGE] file$[, [line][, ALL][, DELETE range]]`\n\nRuns another program from a program, keeping the files that are open.\n\n- Only the variables named in COMMON are passed on, or all of them with `ALL`.\n- `line` is where the new program starts (default its first line).\n- `CHAIN MERGE` adds the file's lines to the program (after deleting `range`) and keeps every variable.\n- `.BAS` is added if the name has no extension.\n\nExample:\n\n```\n10 COMMON SCORE\n20 SCORE = 100: CHAIN \"PART2\"\nRUN\n```\n\nSee also: [COMMON](#ref-common), [MERGE](#ref-merge), [RUN](#ref-run)"},{"title":"CHDIR","id":"ref-chdir","kind":"Statement","body":"*Statement* · `CHDIR path$`\n\nMakes a folder the current one, or a drive the current drive.\n\n- `CHDIR \"GAMES\"`, `CHDIR \"..\"`, `CHDIR \"/\"` move between folders.\n- `CHDIR \"SD:\"` makes the SD card the current drive, `CHDIR \"SD:/GAMES\"` its folder too, `CHDIR \"FLASH:\"` goes back.\n- Errors: `Path not found` (76).\n\nExample:\n\n```\nMKDIR \"GAMES\": CHDIR \"GAMES\": FILES\n```\n\nShows:\n\n```\nFile not found\n3080192 Bytes free\n```\n\nSee also: [MKDIR](#ref-mkdir), [RMDIR](#ref-rmdir), [FILES](#ref-files)"},{"title":"CHR$","id":"ref-chr","kind":"Function","body":"*Function* · `CHR$(n)`\n\nThe character with code `n` (0-255), in the IBM PC character set (see Characters).\n\n- Errors: `Illegal function call` (5) out of range.\n\nExample:\n\n```\nPRINT CHR$(65); CHR$(219); CHR$(1)\n```\n\nShows:\n\n```\nA█☺\n```\n\nSee also: [ASC](#ref-asc), [STRING$](#ref-string)"},{"title":"CINT","id":"ref-cint","kind":"Function","body":"*Function* · `CINT(x)`\n\n`x` rounded to the nearest whole number (halves away from 0), -32768 to 32767.\n\n- Errors: `Overflow` (6) out of range.\n\nExample:\n\n```\nPRINT CINT(2.5); CINT(-2.5); CINT(2.4)\n```\n\nShows:\n\n```\n 3 -3  2\n```\n\nSee also: [INT](#ref-int), [FIX](#ref-fix)"},{"title":"CLEAR","id":"ref-clear","kind":"Statement","body":"*Statement* · `CLEAR [, n[, m]]`\n\nDeletes every variable and array, closes every file, and forgets DATA, FOR, GOSUB and WHILE positions and event traps. The program stays.\n\n- Any numbers after it (memory sizes, for older programs) are accepted and ignored.\n\nExample:\n\n```\nA = 5: CLEAR: PRINT A\n```\n\nShows:\n\n```\n 0\n```\n\nSee also: [NEW](#ref-new), [ERASE](#ref-erase)"},{"title":"CLOSE","id":"ref-close","kind":"Statement","body":"*Statement* · `CLOSE [[#]n[, [#]n...]]`\n\nCloses the files numbered, or all of them. Writes still in memory go to the disk.\n\nExample:\n\n```\nCLOSE #1\n```\n\nSee also: [OPEN](#ref-open), [RESET](#ref-reset)"},{"title":"CLS","id":"ref-cls","kind":"Statement","body":"*Statement* · `CLS [n]`\n\nClears the terminal and puts the cursor at the top left.\n\n- `n` (0-2) is accepted for old programs.\n\nSee also: [LOCATE](#ref-locate), [COLOR](#ref-color)"},{"title":"COLOR","id":"ref-color","kind":"Statement","body":"*Statement* · `COLOR [fg][, [bg][, border]]`\n\nSets the text colours, as PC colours 0-15 sent as ANSI codes: 0 black, 1 blue, 2 green, 3 cyan, 4 red, 5 magenta, 6 brown, 7 white, 8-15 bright. 7 (fg) and 0 (bg) give the terminal's own colours.\n\n- fg 16-31 counts as 0-15 (no blinking). `border` is ignored.\n- Errors: `Illegal function call` (5) out of range.\n\nExample:\n\n```\nCOLOR 14, 1: PRINT \"YELLOW ON BLUE\": COLOR 7, 0\n```\n\nShows:\n\n```\nYELLOW ON BLUE\n```\n\nSee also: [CLS](#ref-cls)"},{"title":"COM(1)","id":"ref-com1","kind":"Statement","body":"*Statement* · `COM(1) ON | OFF | STOP`\n\nTurns the COM1 event (ON COM) on, off, or holds it (remembered until ON).\n\nSee also: [ON COM](#ref-on-com)"},{"title":"COMMON","id":"ref-common","kind":"Statement","body":"*Statement* · `COMMON var[, var...]`\n\nNames the variables CHAIN passes to the next program. Arrays are written with empty brackets: `COMMON A(), N$`.\n\n- Up to 64 names.\n\nExample:\n\n```\nCOMMON SCORE, NAME$\n```\n\nSee also: [CHAIN](#ref-chain)"},{"title":"CONFIG","id":"ref-config","kind":"Command","body":"*Command* · `CONFIG`\n\nShows the board's settings: whether the SD card is used and its pins, the speaker's pin and NEOPIXEL's default pin, from FLASH:/CONFIG.TXT or the build's defaults, and any problems CONFIG.TXT has.\n\n- Change them with `EDIT \"FLASH:CONFIG.TXT\"`; they take effect at the next power-up or reset (see the manual's Settings section).\n\nExample:\n\n```\nCONFIG\n```\n\nShows:\n\n```\nSettings (FLASH:/CONFIG.TXT):\n  SD = OFF\n  SPEAKER = GP18\n  NEOPIXEL = GP28 (NEOPIXEL OPEN's default)\n  TZ = UTC (none set)\n```\n\nSee also: [EDIT](#ref-edit), [NEOPIXEL](#ref-neopixel), [BEEP](#ref-beep)"},{"title":"CONT","id":"ref-cont","kind":"Command","body":"*Command* · `CONT`\n\nCarries on with the program after Ctrl-C or STOP, from where it stopped.\n\n- Errors: `Can't continue` (17) after the program has been changed or after an error.\n\nSee also: [STOP](#ref-stop), [END](#ref-end)"},{"title":"COS","id":"ref-cos","kind":"Function","body":"*Function* · `COS(x)`\n\nThe cosine of `x` radians.\n\nExample:\n\n```\nPRINT COS(0)\n```\n\nShows:\n\n```\n 1\n```\n\nSee also: [SIN](#ref-sin), [TAN](#ref-tan)"},{"title":"CSNG","id":"ref-csng","kind":"Function","body":"*Function* · `CSNG(x)`\n\n`x` as a single-precision number (7 digits).\n\nExample:\n\n```\nPRINT CSNG(1#/3)\n```\n\nShows:\n\n```\n .3333333\n```\n\nSee also: [CDBL](#ref-cdbl)"},{"title":"CSRLIN","id":"ref-csrlin","kind":"Function","body":"*Function* · `CSRLIN`\n\nThe row the cursor is on, 1-30.\n\nExample:\n\n```\nLOCATE 10, 1: PRINT CSRLIN\n```\n\nShows:\n\n```\n 10\n```\n\nSee also: [POS](#ref-pos), [LOCATE](#ref-locate)"},{"title":"CVD","id":"ref-cvd","kind":"Function","body":"*Function* · `CVD(s$)`\n\nThe double-precision number in an 8-byte string made by MKD$ (Microsoft Binary Format).\n\n- Errors: `Illegal function call` (5) for a string shorter than 8.\n\nSee also: [MKD$](#ref-mkd)"},{"title":"CVI","id":"ref-cvi","kind":"Function","body":"*Function* · `CVI(s$)`\n\nThe integer in a 2-byte string made by MKI$ (low byte first).\n\nExample:\n\n```\nPRINT CVI(MKI$(1234))\n```\n\nShows:\n\n```\n 1234\n```\n\nSee also: [MKI$](#ref-mki)"},{"title":"CVS","id":"ref-cvs","kind":"Function","body":"*Function* · `CVS(s$)`\n\nThe single-precision number in a 4-byte string made by MKS$.\n\nExample:\n\n```\nPRINT CVS(MKS$(2.5))\n```\n\nShows:\n\n```\n 2.5\n```\n\nSee also: [MKS$](#ref-mks)"},{"title":"DATA","id":"ref-data","kind":"Statement","body":"*Statement* · `DATA item[, item...]`\n\nHolds numbers and strings for READ. Strings may be quoted (needed if they hold commas or start with spaces).\n\nExample:\n\n```\n10 DATA 3, \"RED\", 2.5\n```\n\nSee also: [READ](#ref-read), [RESTORE](#ref-restore)"},{"title":"DATE$","id":"ref-date","kind":"","body":"*Statement / function* · `DATE$ = \"mm-dd-yyyy\" | DATE$`\n\nSets the date, or gives it as \"mm-dd-yyyy\". `-` or `/` and two-digit years are accepted. There is no battery clock: it starts at 01-01-1970 at power-up (Wi-Fi builds set it by NTP).\n\nExample:\n\n```\nDATE$ = \"10-31-2026\": PRINT DATE$\n```\n\nShows:\n\n```\n10-31-2026\n```\n\nSee also: [TIME$](#ref-time)"},{"title":"DEF FN","id":"ref-def-fn","kind":"Statement","body":"*Statement* · `DEF FNname[(arg[, arg...])] = expr`\n\nDefines a one-line function, called as FNname(...). String functions end in $.\n\n- Only in a program line: in direct mode it is `Illegal direct` (12).\n- Errors: `Undefined user function` (18) for one not defined.\n\nExample:\n\n```\n10 DEF FNSQ(X) = X * X: PRINT FNSQ(7)\nRUN\n```\n\nShows:\n\n```\n 49\n```\n\nSee also: [GOSUB](#ref-gosub)"},{"title":"DEF SEG","id":"ref-def-seg","kind":"Statement","body":"*Statement* · `DEF SEG [= segment]`\n\nChooses the memory segment PEEK, POKE, BSAVE and BLOAD use: only `&HB800` (the text screen) and `0` (BIOS data) are emulated.\n\nExample:\n\n```\nDEF SEG = 0: PRINT PEEK(&H44A)\n```\n\nShows:\n\n```\n 80\n```\n\nSee also: [PEEK](#ref-peek), [POKE](#ref-poke)"},{"title":"DEFDBL","id":"ref-defdbl","kind":"Statement","body":"*Statement* · `DEFDBL letters`\n\nNames starting with these letters (and no type character) are double precision: `DEFDBL A-C, X`.\n\n- RUN, NEW and CLEAR reset it.\n\nExample:\n\n```\nDEFDBL D: D = 1 / 3: PRINT D\n```\n\nShows:\n\n```\n .333333333\n```\n\nSee also: [DEFINT](#ref-defint), [DEFSNG](#ref-defsng), [DEFSTR](#ref-defstr)"},{"title":"DEFINT","id":"ref-defint","kind":"Statement","body":"*Statement* · `DEFINT letters`\n\nNames starting with these letters are integers (-32768 to 32767): `DEFINT A-Z` makes all plain names integers.\n\nExample:\n\n```\nDEFINT I: I = 2.7: PRINT I\n```\n\nShows:\n\n```\n 3\n```\n\nSee also: [DEFDBL](#ref-defdbl), [DEFSNG](#ref-defsng), [DEFSTR](#ref-defstr)"},{"title":"DEFSNG","id":"ref-defsng","kind":"Statement","body":"*Statement* · `DEFSNG letters`\n\nNames starting with these letters are single precision (the default).\n\nSee also: [DEFINT](#ref-defint), [DEFDBL](#ref-defdbl)"},{"title":"DEFSTR","id":"ref-defstr","kind":"Statement","body":"*Statement* · `DEFSTR letters`\n\nNames starting with these letters are strings, without a `$`.\n\nExample:\n\n```\nDEFSTR S: S = \"HI\": PRINT S\n```\n\nShows:\n\n```\nHI\n```\n\nSee also: [DEFINT](#ref-defint)"},{"title":"DELETE","id":"ref-delete","kind":"Command","body":"*Command* · `DELETE range`\n\nDeletes program lines. `range` is `n`, `n-`, `-n` or `n-m`.\n\n- Errors: `Illegal function call` (5) if there is nothing in the range.\n\nExample:\n\n```\nDELETE 100-190\n```\n\nSee also: [NEW](#ref-new), [AUTO](#ref-auto)"},{"title":"DIM","id":"ref-dim","kind":"Statement","body":"*Statement* · `DIM name(size[, size...])[, ...]`\n\nMakes an array with subscripts 0 (or 1 after OPTION BASE 1) to `size`, up to 8 dimensions. An array used without DIM gets 0-10 in each dimension.\n\n- Errors: `Duplicate Definition` (10) if it exists; `Subscript out of range` (9) for a subscript too big; `Out of memory` (7).\n\nExample:\n\n```\nDIM A(5), B$(2, 3): A(5) = 7: PRINT A(5)\n```\n\nShows:\n\n```\n 7\n```\n\nSee also: [ERASE](#ref-erase), [OPTION BASE](#ref-option-base)"},{"title":"DIR$","id":"ref-dir","kind":"Function","body":"*Function* · `DIR$(pattern$[, n])`\n\nThe `n`-th (default 1st) file name matching the pattern, e.g. `DIR$(\"*.BAS\", 2)`; \"\" after the last. For going through a folder's files.\n\nExample:\n\n```\n10 I = 1\n20 F$ = DIR$(\"*.BAS\", I): IF F$ = \"\" THEN END\n30 PRINT F$: I = I + 1: GOTO 20\nRUN\n```\n\nShows:\n\n```\nPRIMES.BAS\nNEODEMO.BAS\n```\n\nSee also: [FILES](#ref-files)"},{"title":"EDIT","id":"ref-edit","kind":"Command","body":"*Command* · `EDIT | EDIT file$ | EDIT n | EDIT .`\n\n`EDIT` opens the program in the full-screen editor (see the manual's Full-screen editor section); `EDIT file$` edits any text file there. `EDIT n` (or `.`, the last line typed or the one that failed) puts program line `n` on the input line to change; Enter stores it.\n\n- In the full-screen editor Ctrl-X/C/V cut, copy and paste lines, Ctrl-Z/R undo and redo, Ctrl-S saves and Esc leaves. A program is only taken if every non-blank line starts with a line number (0-65529, 255 characters at most): otherwise nothing is saved and the cursor goes to the bad line.\n- Leaving without saving keeps the program as it was. Blank lines are left out.\n\nExample:\n\n```\nEDIT 20\n```\n\nShows:\n\n```\n20 PRINT \"HELLO\"\n```\n\nSee also: [LIST](#ref-list), [AUTO](#ref-auto)"},{"title":"END","id":"ref-end","kind":"Statement","body":"*Statement* · `END | END SUB | END FUNCTION`\n\nEnds the program and closes its files. END SUB and END FUNCTION end a SUB or FUNCTION.\n\nExample:\n\n```\n10 PRINT \"DONE\": END\nRUN\n```\n\nShows:\n\n```\nDONE\n```\n\nSee also: [STOP](#ref-stop)"},{"title":"ENVIRON","id":"ref-environ","kind":"Statement","body":"*Statement* · `ENVIRON \"name=value\"`\n\nSets a string ENVIRON$ gives back (there is no DOS environment).\n\nExample:\n\n```\nENVIRON \"USER=KEN\"\n```\n\nSee also: [ENVIRON$](#ref-environ-1)"},{"title":"ENVIRON$","id":"ref-environ-1","kind":"Function","body":"*Function* · `ENVIRON$(name$) | ENVIRON$(n)`\n\nThe value set for `name$` with ENVIRON, or the n-th \"name=value\" string; \"\" if none.\n\nExample:\n\n```\nENVIRON \"USER=KEN\": PRINT ENVIRON$(\"USER\")\n```\n\nShows:\n\n```\nKEN\n```\n\nSee also: [ENVIRON](#ref-environ)"},{"title":"EOF","id":"ref-eof","kind":"Function","body":"*Function* · `EOF(n)`\n\n-1 when file `n` has nothing more to read (for a random file: the last GET was past the end; for COM1: nothing waiting), else 0.\n\nExample:\n\n```\nWHILE NOT EOF(1): LINE INPUT #1, L$: PRINT L$: WEND\n```\n\nSee also: [LOF](#ref-lof), [LOC](#ref-loc)"},{"title":"EQV","id":"ref-eqv","kind":"Operator","body":"*Operator* · `a EQV b`\n\nBitwise equivalence: a bit is 1 where both are the same.\n\nExample:\n\n```\nPRINT -1 EQV 0\n```\n\nShows:\n\n```\n 0\n```\n\nSee also: [XOR](#ref-xor)"},{"title":"ERASE","id":"ref-erase","kind":"Statement","body":"*Statement* · `ERASE array[, array...]`\n\nDeletes arrays, freeing their memory, so they can be dimensioned again.\n\nExample:\n\n```\nDIM A(100): ERASE A: DIM A(5)\n```\n\nSee also: [DIM](#ref-dim)"},{"title":"ERDEV","id":"ref-erdev","kind":"Function","body":"*Function* · `ERDEV | ERDEV$`\n\nDevice error details: always 0 and \"\" here.\n\nSee also: [ERR](#ref-err)"},{"title":"ERL","id":"ref-erl","kind":"Function","body":"*Function* · `ERL`\n\nThe line number where the last error happened (0 in direct mode).\n\nExample:\n\n```\n100 PRINT \"Error\"; ERR; \"in\"; ERL: RESUME NEXT\n```\n\nSee also: [ERR](#ref-err), [ON ERROR GOTO](#ref-on-error-goto)"},{"title":"ERR","id":"ref-err","kind":"Function","body":"*Function* · `ERR`\n\nThe code of the last error (see Error codes).\n\nExample:\n\n```\n10 ON ERROR GOTO 100\n20 X = 1 / 0\n30 END\n100 PRINT ERR: RESUME NEXT\nRUN\n```\n\nShows:\n\n```\n 11\n```\n\nSee also: [ERL](#ref-erl), [ERROR](#ref-error)"},{"title":"ERROR","id":"ref-error","kind":"Statement","body":"*Statement* · `ERROR n`\n\nRaises error `n` (1-255), as if it had happened: a test, or a program's own error codes.\n\n- Codes without a message print `Unprintable error`.\n\nExample:\n\n```\nERROR 53\n```\n\nShows:\n\n```\nFile not found\n```\n\nSee also: [ON ERROR GOTO](#ref-on-error-goto), [ERR](#ref-err)"},{"title":"EXIT FOR","id":"ref-exit-for","kind":"Statement","body":"*Statement* · `EXIT FOR | EXIT SUB | EXIT FUNCTION`\n\nLeaves the innermost FOR loop at once, going on after its NEXT (from QuickBASIC); EXIT SUB and EXIT FUNCTION leave a SUB or FUNCTION.\n\nExample:\n\n```\n10 FOR I = 1 TO 10: IF I = 3 THEN EXIT FOR\n20 NEXT: PRINT I\nRUN\n```\n\nShows:\n\n```\n 3\n```\n\nSee also: [FOR](#ref-for)"},{"title":"EXP","id":"ref-exp","kind":"Function","body":"*Function* · `EXP(x)`\n\ne (2.718...) to the power `x`.\n\n- Errors: `Overflow` (6) if too big.\n\nExample:\n\n```\nPRINT EXP(1)\n```\n\nShows:\n\n```\n 2.71828183\n```\n\nSee also: [LOG](#ref-log)"},{"title":"EXTERR","id":"ref-exterr","kind":"Function","body":"*Function* · `EXTERR(n)`\n\nDOS extended error information: always 0 here.\n\nSee also: [ERR](#ref-err)"},{"title":"FIELD","id":"ref-field","kind":"Statement","body":"*Statement* · `FIELD #n, width AS var$[, width AS var$...]`\n\nDivides random file `n`'s record buffer into string fields (at most 16, no more than the record length). GET fills them; LSET/RSET set them for PUT.\n\n- Errors: `FIELD overflow` (50).\n\nExample:\n\n```\nFIELD #1, 20 AS NM$, 2 AS AGE$\n```\n\nSee also: [GET](#ref-get), [PUT](#ref-put), [LSET](#ref-lset)"},{"title":"FILES","id":"ref-files","kind":"Command","body":"*Command* · `FILES [pattern$][, long]`\n\nLists files, four to a line (folders marked `<DIR>`), then the free space on that drive.\n\n- The pattern may have `*` and `?` and a drive and folder in front: `FILES \"*.BAS\"`, `FILES \"SD:\"`, `FILES \"SD:/GAMES/*.BAS\"`.\n- Without one, all files in the current folder.\n- With `long` not 0 (`FILES \"*\", 1`), one a line: the size in bytes (or `<DIR>`) in 10 columns, two spaces, and the whole name (the four-to-a-line list cuts names at 14 characters). The PC editor reads this.\n- `File not found` is printed (not an error) when nothing matches.\n\nExample:\n\n```\nFILES \"*.BAS\"\n```\n\nShows:\n\n```\nPRIMES.BAS          NEODEMO.BAS\n3084288 Bytes free\n```\n\nSee also: [DIR$](#ref-dir), [KILL](#ref-kill), [CHDIR](#ref-chdir)"},{"title":"FIX","id":"ref-fix","kind":"Function","body":"*Function* · `FIX(x)`\n\n`x` with its fraction cut off (towards 0).\n\nExample:\n\n```\nPRINT FIX(-2.7); FIX(2.7)\n```\n\nShows:\n\n```\n-2  2\n```\n\nSee also: [INT](#ref-int), [CINT](#ref-cint)"},{"title":"FOR","id":"ref-for","kind":"Statement","body":"*Statement* · `FOR v = a TO b [STEP s] ... NEXT [v]`\n\nRepeats the lines up to NEXT with `v` = a, a+s, ... while it hasn't passed `b`. STEP defaults to 1; a negative STEP counts down.\n\n- The loop body is skipped when `a` is already past `b`.\n- Up to 32 loops nested.\n\nExample:\n\n```\nFOR I = 10 TO 1 STEP -3: PRINT I;: NEXT\n```\n\nShows:\n\n```\n 10  7  4  1\n```\n\nSee also: [NEXT](#ref-next), [EXIT FOR](#ref-exit-for), [WHILE](#ref-while)"},{"title":"FORMAT","id":"ref-format","kind":"Command","body":"*Command* · `FORMAT ON | FORMAT OFF | FORMAT n`\n\nWhether LIST, EDIT and SAVE indent the program: FOR ... NEXT and WHILE ... WEND bodies by `n` spaces a level (2 to start with, 1-8), and in a program without line numbers the subroutines (the lines under a label GOSUB calls or ON ERROR GOTO goes to; labels stay at the left).\n\n- Only the look changes: loading a program takes the indent off again.\n- On at start-up.\n\nExample:\n\n```\n10 FOR I = 1 TO 2\n20 PRINT I\n30 NEXT\nLIST\n```\n\nShows:\n\n```\n10 FOR I = 1 TO 2\n20   PRINT I\n30 NEXT\n```\n\nSee also: [LIST](#ref-list), [EDIT](#ref-edit), [SAVE](#ref-save)"},{"title":"FRE","id":"ref-fre","kind":"Function","body":"*Function* · `FRE(x)`\n\nThe memory free for programs and data, in bytes (`x` is ignored).\n\nExample:\n\n```\nPRINT FRE(0)\n```\n\nShows:\n\n```\n 431456\n```"},{"title":"FREEFILE","id":"ref-freefile","kind":"Function","body":"*Function* · `FREEFILE`\n\nThe lowest file number (1-4) not in use.\n\nExample:\n\n```\nF = FREEFILE: OPEN \"LOG.TXT\" FOR APPEND AS #F\n```\n\nSee also: [OPEN](#ref-open)"},{"title":"FUNCTION","id":"ref-function","kind":"Statement","body":"*Statement* · `FUNCTION name[(param[, param...])] ... END FUNCTION`\n\nA function of several lines, used in expressions as `name(args)`: it gives back what was last given to `name`. EXIT FUNCTION leaves it early. String functions end in $.\n\n- Its variables are its own, as for SUB; arguments are copies.\n- An error in a FUNCTION going to ON ERROR is the calling statement's: RESUME NEXT goes on after it.\n- Errors: `Wrong number of arguments` (86), `FUNCTION without END FUNCTION` (83), `END FUNCTION without FUNCTION` (85).\n\nExample:\n\n```\nFUNCTION FACT(N)\n  IF N <= 1 THEN FACT = 1 ELSE FACT = N * FACT(N - 1)\nEND FUNCTION\nPRINT FACT(10)\n```\n\nShows:\n\n```\n 3628800\n```\n\nSee also: [SUB](#ref-sub), [DEF FN](#ref-def-fn)"},{"title":"GET","id":"ref-get","kind":"Statement","body":"*Statement* · `GET [#]n[, record]`\n\nReads record `record` (from 1; default the next) of random file `n` into its buffer and FIELD variables.\n\n- Errors: `Bad record number` (63).\n\nExample:\n\n```\nGET #1, 3: PRINT NM$\n```\n\nSee also: [PUT](#ref-put), [FIELD](#ref-field)"},{"title":"GOSUB","id":"ref-gosub","kind":"Statement","body":"*Statement* · `GOSUB line | GOSUB label`\n\nCalls the subroutine at `line` (or `label`); RETURN comes back to the statement after the GOSUB.\n\n- Up to 32 deep.\n- Errors: `Undefined line number` (8), `Undefined label` (80).\n\nExample:\n\n```\n10 GOSUB 100: END\n100 PRINT \"SUB\": RETURN\nRUN\n```\n\nShows:\n\n```\nSUB\n```\n\nSee also: [RETURN](#ref-return), [ON...GOSUB](#ref-ongosub)"},{"title":"GOTO","id":"ref-goto","kind":"Statement","body":"*Statement* · `GOTO line | GOTO label`\n\nGoes on at `line`, or at the line that starts with `label:` (a name and a colon).\n\n- Labels: letters, digits, `.` and `_`, up to 40, any case; a program can have them with line numbers or without.\n- Errors: `Undefined line number` (8), `Undefined label` (80), `Duplicate label` (81, at RUN).\n\nExample:\n\n```\n10 PRINT \"HI\": GOTO 10\nRUN\n```\n\nShows:\n\n```\nHI\nHI\n...\n```\n\nSee also: [GOSUB](#ref-gosub), [IF](#ref-if)"},{"title":"HEX$","id":"ref-hex","kind":"Function","body":"*Function* · `HEX$(n)`\n\n`n` (-32768 to 65535) in hexadecimal; negative numbers as their 16-bit two's complement.\n\n- Errors: `Overflow` (6) out of range.\n\nExample:\n\n```\nPRINT HEX$(255); \" \"; HEX$(-1)\n```\n\nShows:\n\n```\nFF FFFF\n```\n\nSee also: [OCT$](#ref-oct), [VAL](#ref-val)"},{"title":"I2C","id":"ref-i2c","kind":"Statement","body":"*Statement* · `I2C OPEN [sda, scl[, khz]] | I2C WRITE addr, item[, item...][, NOSTOP] | I2C SCAN | I2C CLOSE`\n\nThe chip's I2C. OPEN starts it (default GP2 SDA, GP3 SCL, I2C1, 100 kHz; 10-1000), WRITE sends bytes (numbers 0-255 and strings) to device `addr` (0-127) (NOSTOP keeps the bus for a read), SCAN lists the devices that answer, CLOSE frees the pins.\n\n- SDA on an even pin, SCL the next one.\n- Errors: `Device I/O error` (57) if no device answers, `Device unavailable` (68) before OPEN.\n\nExample:\n\n```\nI2C OPEN: I2C SCAN\n```\n\nSee also: [I2CREAD](#ref-i2cread), [SPI](#ref-spi)"},{"title":"I2CREAD","id":"ref-i2cread","kind":"Function","body":"*Function* · `I2CREAD(addr[, reg])`\n\nReads one byte from I2C device `addr`; with `reg`, first writes the register number.\n\nExample:\n\n```\nPRINT I2CREAD(&H68, &H75)\n```\n\nShows:\n\n```\n 104\n```\n\nSee also: [I2CREAD$](#ref-i2cread-1), [I2C](#ref-i2c)"},{"title":"I2CREAD$","id":"ref-i2cread-1","kind":"Function","body":"*Function* · `I2CREAD$(addr, n[, reg])`\n\nReads `n` bytes (1-255) from I2C device `addr` as a string; with `reg`, from that register.\n\nExample:\n\n```\nD$ = I2CREAD$(&H68, 6, &H3B)\n```\n\nSee also: [I2CREAD](#ref-i2cread)"},{"title":"IF","id":"ref-if","kind":"Statement","body":"*Statement* · `IF cond THEN statements [ELSE statements] | IF cond THEN line | IF cond GOTO line`\n\nRuns the statements after THEN when `cond` is not 0 (true), else those after ELSE. A line number or label after THEN or ELSE jumps there (a label when nothing else follows it).\n\n- Comparisons give -1 (true) or 0 (false); any number not 0 counts as true.\n- Everything to the end of the line belongs to THEN or ELSE.\n\nExample:\n\n```\nA = 5: IF A > 3 THEN PRINT \"BIG\" ELSE PRINT \"SMALL\"\n```\n\nShows:\n\n```\nBIG\n```\n\nSee also: [WHILE](#ref-while), [ON...GOTO](#ref-ongoto)"},{"title":"IMP","id":"ref-imp","kind":"Operator","body":"*Operator* · `a IMP b`\n\nBitwise implication: false only where `a` is true and `b` false.\n\nExample:\n\n```\nPRINT 0 IMP 0\n```\n\nShows:\n\n```\n-1\n```\n\nSee also: [EQV](#ref-eqv)"},{"title":"INCLUDE","id":"ref-include","kind":"Statement","body":"*Statement* · `INCLUDE file$`\n\nIn a program, on a line of its own: when the program runs, the library file's lines (labelled subroutines, no line numbers) go after the program's, so GOSUB can call them.\n\n- `.BAS` is added if the name has no extension. Each file comes in once; a library may INCLUDE others; up to 16 files.\n- LIST, SAVE and EDIT leave the libraries out; each RUN reads them again.\n- An error in a library names it: `Division by zero in line 5 of OLEDLIB.BAS`.\n- Errors: `File not found` (53), `Bad file mode` (54) for a file with line numbers, `Illegal direct` (12) in direct mode.\n\nExample:\n\n```\nINCLUDE \"OLEDLIB\"\nGOSUB oledstart\n```\n\nSee also: [GOSUB](#ref-gosub), [CHAIN](#ref-chain), [MERGE](#ref-merge)"},{"title":"INKEY$","id":"ref-inkey","kind":"Function","body":"*Function* · `INKEY$`\n\nThe key waiting, or \"\" if none: it doesn't wait. Cursor and function keys give CHR$(0) and the PC scan code (see INKEY$ key codes).\n\nExample:\n\n```\nK$ = INKEY$: IF K$ = CHR$(0) + CHR$(72) THEN PRINT \"UP\"\n```\n\nSee also: [INPUT$](#ref-input-2), [ON KEY](#ref-on-key)"},{"title":"INPUT","id":"ref-input","kind":"Statement","body":"*Statement* · `INPUT [\"prompt\"{; | ,}] var[, var...]`\n\nWaits for a line typed at the terminal and puts its comma-separated items into the variables. A `;` after the prompt adds `? `, a `,` doesn't.\n\n- If the items don't fit (too few, or text for a number) it says `?Redo from start` and asks again.\n- Ctrl-C stops the program.\n\nExample:\n\n```\nINPUT \"Age\"; A: PRINT A * 12; \"months\"\n```\n\nShows:\n\n```\nAge? 3\n 36 months\n```\n\nSee also: [LINE INPUT](#ref-line-input), [INPUT #](#ref-input-1)"},{"title":"INPUT #","id":"ref-input-1","kind":"Statement","body":"*Statement* · `INPUT #n, var[, var...]`\n\nReads items from file `n`: quoted strings, or text up to a comma or the end of the line (numbers stop at a space too).\n\n- Errors: `Input past end` (62).\n\nExample:\n\n```\nINPUT #1, N$, S\n```\n\nSee also: [WRITE #](#ref-write-1), [LINE INPUT #](#ref-line-input-1)"},{"title":"INPUT$","id":"ref-input-2","kind":"Function","body":"*Function* · `INPUT$(n[, [#]f])`\n\nReads `n` characters: from file `f`, or from the keyboard (waiting, without showing them).\n\nExample:\n\n```\nK$ = INPUT$(1): PRINT \"You pressed \"; K$\n```\n\nShows:\n\n```\nYou pressed A\n```\n\nSee also: [INKEY$](#ref-inkey), [INPUT](#ref-input)"},{"title":"INSTR","id":"ref-instr","kind":"Function","body":"*Function* · `INSTR([start,] s$, find$)`\n\nWhere `find$` first appears in `s$` (from position `start`, default 1); 0 if it doesn't.\n\nExample:\n\n```\nPRINT INSTR(\"HELLO\", \"L\"); INSTR(4, \"HELLO\", \"L\")\n```\n\nShows:\n\n```\n 3  4\n```\n\nSee also: [MID$](#ref-mid)"},{"title":"INT","id":"ref-int","kind":"Function","body":"*Function* · `INT(x)`\n\nThe largest whole number not more than `x` (rounds down).\n\nExample:\n\n```\nPRINT INT(-2.5); INT(2.5)\n```\n\nShows:\n\n```\n-3  2\n```\n\nSee also: [FIX](#ref-fix), [CINT](#ref-cint)"},{"title":"KEY","id":"ref-key","kind":"Statement","body":"*Statement* · `KEY n, text$ | KEY LIST | KEY ON | KEY OFF`\n\nSets what function key F1-F10 types (`CHR$(13)` in it is Enter), lists them, or shows their labels on row 25 (`KEY ON`) as on a PC.\n\n- Defaults: F1 `LIST `, F2 `RUN`+Enter, F3 `LOAD\"`, F4 `SAVE\"`, F5 `CONT`+Enter, F7 `TRON`, F8 `TROFF`, F9 `KEY `, F10 `SCREEN 0,0,0`.\n- `KEY(n) ON/OFF/STOP` is for key events: see ON KEY.\n\nExample:\n\n```\nKEY 5, \"FILES\" + CHR$(13)\n```\n\nSee also: [ON KEY](#ref-on-key)"},{"title":"KEY(n)","id":"ref-keyn","kind":"Statement","body":"*Statement* · `KEY(n) ON | OFF | STOP`\n\nTurns key `n`'s event (ON KEY) on, off, or holds it.\n\nExample:\n\n```\nKEY(1) ON\n```\n\nSee also: [ON KEY](#ref-on-key)"},{"title":"KILL","id":"ref-kill","kind":"Statement","body":"*Statement* · `KILL file$`\n\nDeletes a file. No extension is added.\n\n- Errors: `File not found` (53); `File already open` (55) while it is open.\n\nExample:\n\n```\nKILL \"OLD.BAS\"\n```\n\nSee also: [NAME](#ref-name), [FILES](#ref-files)"},{"title":"LCASE$","id":"ref-lcase","kind":"Function","body":"*Function* · `LCASE$(s$)`\n\n`s$` in lower case.\n\nExample:\n\n```\nPRINT LCASE$(\"Hello\")\n```\n\nShows:\n\n```\nhello\n```\n\nSee also: [UCASE$](#ref-ucase)"},{"title":"LEFT$","id":"ref-left","kind":"Function","body":"*Function* · `LEFT$(s$, n)`\n\nThe first `n` characters of `s$`.\n\nExample:\n\n```\nPRINT LEFT$(\"HELLO\", 2)\n```\n\nShows:\n\n```\nHE\n```\n\nSee also: [RIGHT$](#ref-right), [MID$](#ref-mid)"},{"title":"LEN","id":"ref-len","kind":"Function","body":"*Function* · `LEN(s$)`\n\nThe number of characters in `s$` (0-255).\n\nExample:\n\n```\nPRINT LEN(\"HELLO\")\n```\n\nShows:\n\n```\n 5\n```"},{"title":"LET","id":"ref-let","kind":"Statement","body":"*Statement* · `[LET] var = expr`\n\nGives a variable a value. `LET` itself is optional.\n\n- Errors: `Type mismatch` (13) for a string into a number or the other way; `Overflow` (6) out of an integer's range.\n\nExample:\n\n```\nLET A = 5: B$ = \"X\"\n```\n\nSee also: [SWAP](#ref-swap)"},{"title":"LINE INPUT","id":"ref-line-input","kind":"Statement","body":"*Statement* · `LINE INPUT [\"prompt\";] var$`\n\nReads a whole line typed at the terminal, commas and quotes included, into a string.\n\nExample:\n\n```\nLINE INPUT \"Name: \"; N$\n```\n\nShows:\n\n```\nName: Ada Lovelace\n```\n\nSee also: [INPUT](#ref-input)"},{"title":"LINE INPUT #","id":"ref-line-input-1","kind":"Statement","body":"*Statement* · `LINE INPUT #n, var$`\n\nReads a whole line of file `n` into a string.\n\nExample:\n\n```\nLINE INPUT #1, L$\n```\n\nSee also: [INPUT #](#ref-input-1)"},{"title":"LIST","id":"ref-list","kind":"Command","body":"*Command* · `LIST [range]`\n\nLists the program, pausing after each 28 lines (any key goes on, Q stops). `range` is `n`, `n-`, `-n` or `n-m`.\n\nExample:\n\n```\nLIST 10-30\n```\n\nShows:\n\n```\n10 PRINT \"HELLO\"\n20 GOTO 10\n```\n\nSee also: [LLIST](#ref-llist), [EDIT](#ref-edit)"},{"title":"LLIST","id":"ref-llist","kind":"Command","body":"*Command* · `LLIST [range]`\n\nThe same as LIST: there is no printer.\n\nSee also: [LIST](#ref-list)"},{"title":"LOAD","id":"ref-load","kind":"Command","body":"*Command* · `LOAD file$[, R]`\n\nLoads a program, replacing the one in memory; with `,R` runs it too.\n\n- `.BAS` is added if the name has no extension.\n- Plain text (CR LF or LF lines) and tokenised (binary) BASIC files from a PC are read.\n- Errors: `File not found` (53).\n\nExample:\n\n```\nLOAD \"PRIMES\": RUN\n```\n\nShows:\n\n```\n 168 primes below 1000\n```\n\nSee also: [SAVE](#ref-save), [RUN](#ref-run), [MERGE](#ref-merge)"},{"title":"LOC","id":"ref-loc","kind":"Function","body":"*Function* · `LOC(n)`\n\nFor a random file: the last record read or written. For COM1: the bytes waiting. Otherwise the position in 128-byte blocks.\n\nSee also: [LOF](#ref-lof), [EOF](#ref-eof)"},{"title":"LOCATE","id":"ref-locate","kind":"Statement","body":"*Statement* · `LOCATE [row][, [col][, cursor]]`\n\nMoves the cursor to `row` (1-30) and `col` (1-80); `cursor` 0 hides it, 1 shows it.\n\n- Errors: `Illegal function call` (5) off the screen.\n\nExample:\n\n```\nLOCATE 12, 35: PRINT \"MIDDLE\"\n```\n\nSee also: [CSRLIN](#ref-csrlin), [POS](#ref-pos)"},{"title":"LOF","id":"ref-lof","kind":"Function","body":"*Function* · `LOF(n)`\n\nThe length of file `n` in bytes (for COM1: the room left in its buffer).\n\nExample:\n\n```\nOPEN \"PRIMES.BAS\" FOR INPUT AS #1: PRINT LOF(1): CLOSE\n```\n\nShows:\n\n```\n 329\n```\n\nSee also: [LOC](#ref-loc)"},{"title":"LOG","id":"ref-log","kind":"Function","body":"*Function* · `LOG(x)`\n\nThe natural logarithm of `x` (> 0). LOG(x) / LOG(10) is the base-10 log.\n\n- Errors: `Illegal function call` (5) for 0 or less.\n\nExample:\n\n```\nPRINT LOG(100) / LOG(10)\n```\n\nShows:\n\n```\n 2\n```\n\nSee also: [EXP](#ref-exp)"},{"title":"LPRINT","id":"ref-lprint","kind":"Statement","body":"*Statement* · `LPRINT items | LPRINT USING fmt$; items`\n\nThe same as PRINT: there is no printer.\n\nSee also: [PRINT](#ref-print)"},{"title":"LSET","id":"ref-lset","kind":"Statement","body":"*Statement* · `LSET var$ = s$`\n\nPuts `s$` in a FIELD variable, left-aligned and padded with spaces (cut if too long). Use it, not LET, for field variables.\n\nExample:\n\n```\nLSET NM$ = \"Grace\"\n```\n\nSee also: [RSET](#ref-rset), [FIELD](#ref-field)"},{"title":"MERGE","id":"ref-merge","kind":"Command","body":"*Command* · `MERGE file$`\n\nAdds the lines of a plain-text program to the one in memory; lines with the same number are replaced.\n\nExample:\n\n```\nMERGE \"SUBS\"\n```\n\nSee also: [LOAD](#ref-load), [CHAIN](#ref-chain)"},{"title":"MID$","id":"ref-mid","kind":"Function","body":"*Function* · `MID$(s$, start[, n])`\n\nUp to `n` characters of `s$` from position `start` (all the rest without `n`).\n\n- Errors: `Illegal function call` (5) for `start` < 1.\n\nExample:\n\n```\nPRINT MID$(\"HELLO\", 2, 3)\n```\n\nShows:\n\n```\nELL\n```\n\nSee also: [LEFT$](#ref-left), [RIGHT$](#ref-right), [MID$ =](#ref-mid-1)"},{"title":"MID$ =","id":"ref-mid-1","kind":"Statement","body":"*Statement* · `MID$(v$, start[, n]) = x$`\n\nReplaces characters of `v$` in place, from `start`, with those of `x$` (at most `n`); `v$` keeps its length.\n\nExample:\n\n```\nA$ = \"HELLO\": MID$(A$, 2, 3) = \"ipp\": PRINT A$\n```\n\nShows:\n\n```\nHippO\n```\n\nSee also: [MID$](#ref-mid)"},{"title":"MKD$","id":"ref-mkd","kind":"Function","body":"*Function* · `MKD$(x)`\n\nThe number `x` as an 8-byte double-precision string, for random files.\n\nSee also: [CVD](#ref-cvd)"},{"title":"MKDIR","id":"ref-mkdir","kind":"Statement","body":"*Statement* · `MKDIR path$`\n\nMakes a folder.\n\n- Errors: `Path/File Access Error` (75) if it exists.\n\nExample:\n\n```\nMKDIR \"SD:/GAMES\"\n```\n\nSee also: [CHDIR](#ref-chdir), [RMDIR](#ref-rmdir)"},{"title":"MKI$","id":"ref-mki","kind":"Function","body":"*Function* · `MKI$(n)`\n\nThe integer `n` (-32768 to 32767) as a 2-byte string, low byte first.\n\n- Errors: `Overflow` (6).\n\nExample:\n\n```\nPRINT LEN(MKI$(5))\n```\n\nShows:\n\n```\n 2\n```\n\nSee also: [CVI](#ref-cvi)"},{"title":"MKS$","id":"ref-mks","kind":"Function","body":"*Function* · `MKS$(x)`\n\nThe number `x` as a 4-byte single-precision string (Microsoft Binary Format).\n\nSee also: [CVS](#ref-cvs)"},{"title":"MQTT","id":"ref-mqtt","kind":"Statement","body":"*Statement* · `MQTT CONNECT [broker$[, port]] | MQTT DISCONNECT | MQTT PUBLISH topic$, payload$[, qos[, retain]] | MQTT SUBSCRIBE topic$[, qos] | MQTT UNSUBSCRIBE topic$ | MQTT ON|OFF|STOP | MQTT`\n\nMQTT (3.1.1) on Wi-Fi builds: connects to a broker (CONFIG.TXT's `MQTT_BROKER` without `broker$`; port 1883), publishes, and subscribes (+ and # wildcards, 8 at most); messages that come wait in a queue of 8 for MQTT$(0). `MQTT ON`, `OFF` and `STOP` switch ON MQTT's trap; `MQTT` alone shows the state.\n\n- CONNECT waits up to 10 seconds and keeps trying after that; a lost connection is made again (and the subscriptions) every 5 seconds.\n- Errors: `Device I/O error` (57) with the reason (not connected, refused...); `Feature not available` (73) without Wi-Fi.\n\nExample:\n\n```\nMQTT CONNECT \"192.168.1.227\": MQTT PUBLISH \"test/topic\", \"hello\"\n```\n\nSee also: [MQTT()](#ref-mqtt-1), [ON MQTT](#ref-on-mqtt), [WIFI](#ref-wifi)"},{"title":"MQTT()","id":"ref-mqtt-1","kind":"Function","body":"*Function* · `MQTT(n) | MQTT$(n)`\n\n`MQTT(0)` is -1 while connected to the broker, `MQTT(1)` the messages waiting, `MQTT(2)` the messages dropped (the queue was full). `MQTT$(0)` takes the next message and gives its topic (\"\" if none); `MQTT$(1)` is then its payload (up to 255 characters).\n\n- Without Wi-Fi: 0 and \"\".\n\nExample:\n\n```\nWHILE MQTT(1): T$ = MQTT$(0): PRINT T$; \" = \"; MQTT$(1): WEND\n```\n\nSee also: [MQTT](#ref-mqtt), [ON MQTT](#ref-on-mqtt)"},{"title":"NAME","id":"ref-name","kind":"Statement","body":"*Statement* · `NAME old$ AS new$`\n\nRenames a file (or moves it to another folder on the same drive).\n\n- Errors: `File not found` (53), `File already exists` (58).\n\nExample:\n\n```\nNAME \"A.BAS\" AS \"B.BAS\"\n```\n\nSee also: [KILL](#ref-kill)"},{"title":"NEOPIXEL","id":"ref-neopixel","kind":"Statement","body":"*Statement* · `NEOPIXEL OPEN [pin[, count[, order$]]] | NEOPIXEL n, r, g, b | NEOPIXEL FILL r, g, b | NEOPIXEL SHOW | NEOPIXEL BRIGHT level | NEOPIXEL CLEAR | NEOPIXEL CLOSE`\n\nWS2812B LEDs (\"NeoPixels\") on one pin, through a PIO state machine. OPEN sets up `count` (1-1024, default 1) LEDs on `pin` (default GP28, the Maker Pi Pico's RGB LED), GRB order or \"RGB\"; `n, r, g, b` and FILL set colours (0-255) in the buffer; SHOW sends it; BRIGHT (0-255) scales the next SHOWs; CLEAR turns them all off; CLOSE frees the pin.\n\n- Errors: `Device unavailable` (68) before OPEN, `Illegal function call` (5) for a value out of range.\n- RUN, NEW and SYSTEM close it.\n\nExample:\n\n```\nNEOPIXEL OPEN: NEOPIXEL BRIGHT 40: NEOPIXEL 0, 255, 0, 0: NEOPIXEL SHOW\n```\n\nSee also: [PIN](#ref-pin), [PWM](#ref-pwm)"},{"title":"NEW","id":"ref-new","kind":"Command","body":"*Command* · `NEW`\n\nDeletes the program and its variables, closes files, and frees the pins BASIC used.\n\nSee also: [CLEAR](#ref-clear), [DELETE](#ref-delete)"},{"title":"NEXT","id":"ref-next","kind":"Statement","body":"*Statement* · `NEXT [v[, v...]]`\n\nEnds a FOR loop: adds the step and goes round again unless the end is passed. `NEXT J, I` ends two loops.\n\n- Errors: `NEXT without FOR` (1).\n\nExample:\n\n```\nFOR I = 1 TO 3: PRINT I;: NEXT I\n```\n\nShows:\n\n```\n 1  2  3\n```\n\nSee also: [FOR](#ref-for)"},{"title":"NOT","id":"ref-not","kind":"Operator","body":"*Operator* · `NOT a`\n\nBitwise NOT: -1 becomes 0 and 0 becomes -1 (NOT x is -x - 1).\n\nExample:\n\n```\nPRINT NOT 0; NOT 5\n```\n\nShows:\n\n```\n-1 -6\n```\n\nSee also: [AND](#ref-and)"},{"title":"NTP","id":"ref-ntp","kind":"Command","body":"*Command* · `NTP`\n\nAsks the NTP server (`NTP_SERVER` in CONFIG.TXT, pool.ntp.org to start with) for the time now, sets the clock, and prints it as local time (`TZ`). Waits up to 5 seconds.\n\n- Wi-Fi builds only; BASIC asks by itself once connected, and every hour.\n\nExample:\n\n```\nNTP\n```\n\nShows:\n\n```\n2026-10-31 18:30:05 EDT (from pool.ntp.org)\n```\n\nSee also: [WIFI](#ref-wifi), [TIME$](#ref-time), [DATE$](#ref-date)"},{"title":"NUMBERS","id":"ref-numbers","kind":"Command","body":"*Command* · `NUMBERS OFF | NUMBERS ON`\n\n`NUMBERS OFF` takes the line numbers off the program: each line a GOTO, GOSUB, THEN, ELSE, RESTORE, RESUME or RUN goes to gets a label, L and its old number (`L100:`), and those use the label. `NUMBERS ON` numbers the lines 10, 20, 30... again, keeping the labels.\n\n- A program without numbers is listed, saved and edited without them; its lines' numbers (in errors, ERL, TRON) are their lines in the file.\n- Numbers compared with ERL (`IF ERL = 100`) aren't changed.\n\nExample:\n\n```\n10 PRINT \"HI\": GOTO 10\nNUMBERS OFF\nLIST\n```\n\nShows:\n\n```\nL10: PRINT \"HI\": GOTO L10\n```\n\nSee also: [RENUM](#ref-renum), [GOTO](#ref-goto), [EDIT](#ref-edit)"},{"title":"OCT$","id":"ref-oct","kind":"Function","body":"*Function* · `OCT$(n)`\n\n`n` (-32768 to 65535) in octal.\n\nExample:\n\n```\nPRINT OCT$(8)\n```\n\nShows:\n\n```\n10\n```\n\nSee also: [HEX$](#ref-hex)"},{"title":"ON COM","id":"ref-on-com","kind":"Statement","body":"*Statement* · `ON COM(1) GOSUB line`\n\nCalls the subroutine when bytes arrive on the open COM1 (with COM(1) ON).\n\nSee also: [COM(1)](#ref-com1), [OPEN](#ref-open)"},{"title":"ON ERROR GOTO","id":"ref-on-error-goto","kind":"Statement","body":"*Statement* · `ON ERROR GOTO line | ON ERROR GOTO label | ON ERROR GOTO 0`\n\nSends errors in a running program to an error handler at `line`. `ON ERROR GOTO 0` turns that off; inside a handler it reports the error and stops.\n\n- ERR and ERL say what and where; RESUME ends the handler.\n- Ctrl-C can't be trapped.\n- A program that ends inside a handler stops with `No RESUME` (19).\n\nExample:\n\n```\n10 ON ERROR GOTO 100\n20 OPEN \"NONE\" FOR INPUT AS #1\n30 END\n100 PRINT \"no file\": RESUME 30\nRUN\n```\n\nShows:\n\n```\nno file\n```\n\nSee also: [RESUME](#ref-resume), [ERR](#ref-err), [ERROR](#ref-error)"},{"title":"ON KEY","id":"ref-on-key","kind":"Statement","body":"*Statement* · `ON KEY(n) GOSUB line`\n\nCalls the subroutine when key `n` is pressed (with KEY(n) ON): 1-10 are F1-F10, 11 Up, 12 Left, 13 Right, 14 Down.\n\n- `KEY 15`-`KEY 20` user keys are accepted but never trigger.\n\nExample:\n\n```\n10 ON KEY(1) GOSUB 100: KEY(1) ON\n20 GOTO 20\n100 PRINT \"F1\": RETURN\nRUN\n```\n\nShows:\n\n```\nF1\n```\n\nSee also: [KEY(n)](#ref-keyn), [INKEY$](#ref-inkey)"},{"title":"ON MQTT","id":"ref-on-mqtt","kind":"Statement","body":"*Statement* · `ON MQTT GOSUB line`\n\nCalls the subroutine at `line` (or a label) when an MQTT message is waiting, once MQTT ON has switched the trap on; it should take the message with MQTT$(0).\n\n- Checked between statements, like ON KEY; MQTT STOP holds it, MQTT OFF turns it off.\n\nExample:\n\n```\n10 ON MQTT GOSUB 100: MQTT ON\n20 GOTO 20\n100 PRINT MQTT$(0); \" = \"; MQTT$(1): RETURN\n```\n\nSee also: [MQTT](#ref-mqtt), [MQTT()](#ref-mqtt-1)"},{"title":"ON PLAY","id":"ref-on-play","kind":"Statement","body":"*Statement* · `ON PLAY(n) GOSUB line`\n\nCalls the subroutine when PLAY's background queue drops below `n` notes (with PLAY ON): for music that never stops.\n\nSee also: [PLAY](#ref-play), [PLAY ON](#ref-play-on)"},{"title":"ON TIMER","id":"ref-on-timer","kind":"Statement","body":"*Statement* · `ON TIMER(s) GOSUB line`\n\nCalls the subroutine every `s` seconds (1-86400), with TIMER ON.\n\nExample:\n\n```\n10 ON TIMER(1) GOSUB 100: TIMER ON\n20 GOTO 20\n100 PRINT TIME$: RETURN\nRUN\n```\n\nShows:\n\n```\n12:00:01\n12:00:02\n```\n\nSee also: [TIMER ON](#ref-timer-on)"},{"title":"ON...GOSUB","id":"ref-ongosub","kind":"Statement","body":"*Statement* · `ON n GOSUB line1[, line2...] (lines or labels)`\n\nCalls the n-th subroutine in the list. If `n` is 0 or past the list, it goes on with the next statement.\n\nExample:\n\n```\n10 ON 2 GOSUB 100, 200: END\n100 PRINT \"A\": RETURN\n200 PRINT \"B\": RETURN\nRUN\n```\n\nShows:\n\n```\nB\n```\n\nSee also: [ON...GOTO](#ref-ongoto), [GOSUB](#ref-gosub)"},{"title":"ON...GOTO","id":"ref-ongoto","kind":"Statement","body":"*Statement* · `ON n GOTO line1[, line2...] (lines or labels)`\n\nGoes to the n-th line in the list; with `n` 0 or past the list, goes on.\n\nExample:\n\n```\nON 1 GOTO 100, 200\n```\n\nSee also: [ON...GOSUB](#ref-ongosub)"},{"title":"OPEN","id":"ref-open","kind":"Statement","body":"*Statement* · `OPEN file$ FOR INPUT | OUTPUT | APPEND | RANDOM AS [#]n [LEN = size] | OPEN mode$, [#]n, file$[, size] | OPEN \"COM1:...\" AS [#]n`\n\nOpens a file as number `n` (1-4). OUTPUT creates or empties it, APPEND adds to its end, INPUT reads it, RANDOM reads and writes fixed-size records (LEN 1-1024, default 128; also the default without FOR).\n\n- The short form takes \"I\", \"O\", \"A\" or \"R\".\n- A \"COM1:\" name opens the serial port: see the manual's COM1 section.\n- Errors: `File not found` (53), `File already open` (55), `Bad file number` (52).\n\nExample:\n\n```\nOPEN \"SCORES.TXT\" FOR OUTPUT AS #1: PRINT #1, \"Ann\", 120: CLOSE #1\n```\n\nSee also: [CLOSE](#ref-close), [PRINT #](#ref-print-1), [INPUT #](#ref-input-1)"},{"title":"OPTION BASE","id":"ref-option-base","kind":"Statement","body":"*Statement* · `OPTION BASE 0 | 1`\n\nThe lowest array subscript, before any array is used.\n\nExample:\n\n```\nOPTION BASE 1: DIM A(3)\n```\n\nSee also: [DIM](#ref-dim)"},{"title":"OR","id":"ref-or","kind":"Operator","body":"*Operator* · `a OR b`\n\nBitwise OR: true if either is.\n\nExample:\n\n```\nPRINT 12 OR 3\n```\n\nShows:\n\n```\n 15\n```\n\nSee also: [AND](#ref-and), [XOR](#ref-xor)"},{"title":"PAUSE","id":"ref-pause","kind":"Statement","body":"*Statement* · `PAUSE ms`\n\nWaits `ms` milliseconds (an extension); Ctrl-C still stops it.\n\nExample:\n\n```\nPAUSE 500\n```\n\nSee also: [TIMER](#ref-timer)"},{"title":"PEEK","id":"ref-peek","kind":"Function","body":"*Function* · `PEEK(offset)`\n\nA byte of the emulated memory chosen by DEF SEG: the text screen (&HB800: reads spaces and colour 7, as a terminal can't be read) or BIOS data (DEF SEG = 0: &H449 mode 3, &H44A columns 80, &H484 rows-1 29, &H46C-&H46E timer ticks).\n\n- Errors: `Illegal function call` (5) anywhere else.\n\nExample:\n\n```\nDEF SEG = 0: PRINT PEEK(&H44A)\n```\n\nShows:\n\n```\n 80\n```\n\nSee also: [POKE](#ref-poke), [DEF SEG](#ref-def-seg)"},{"title":"PIN","id":"ref-pin","kind":"","body":"*Statement / function* · `PIN pin, level | PIN(pin)`\n\n`PIN pin, level` drives a pin high (1) or low (0), making it an output first. `PIN(pin)` reads it (0 or 1), making an unused pin an input. `LED` stands for the board's LED (GP25).\n\n- Pins BASIC uses (the speaker, SD card, PSRAM, open I2C/SPI/COM1/NeoPixel) are refused: `GPn is used by ...` then `Illegal function call`.\n- On the Maker Pi Pico the buttons GP20-22 read 0 when pressed (turn their pull-ups on with PINMODE).\n\nExample:\n\n```\nPIN LED, 1: PRINT PIN(20)\n```\n\nShows:\n\n```\n 1\n```\n\nSee also: [PINMODE](#ref-pinmode), [PINS](#ref-pins), [PWM](#ref-pwm)"},{"title":"PINMODE","id":"ref-pinmode","kind":"Statement","body":"*Statement* · `PINMODE pin, INPUT | OUTPUT | PULLUP | PULLDOWN`\n\nSets a pin up as an input, an output, or an input with its pull-up or pull-down (or modes 0-3).\n\n- On the RP2350 a pull-down may not pull a pin low (its erratum E9); pull-ups are fine.\n\nExample:\n\n```\nPINMODE 20, PULLUP: PRINT PIN(20)\n```\n\nShows:\n\n```\n 1\n```\n\nSee also: [PIN](#ref-pin)"},{"title":"PINS","id":"ref-pins","kind":"Command","body":"*Command* · `PINS`\n\nLists every pin and what it is doing (free, in, out, PWM, ADC, the speaker, SD card, I2C, SPI, COM1, NeoPixel...).\n\nExample:\n\n```\nPINS\n```\n\nShows:\n\n```\nGP0  free           GP8  free  ...\n```\n\nSee also: [PIN](#ref-pin)"},{"title":"PLAY","id":"ref-play","kind":"Statement","body":"*Statement* · `PLAY music$`\n\nPlays notes in the music language (see the manual's Sound section: A-G, O, L, T, P, MF/MB...).\n\n- After `MB` the notes play in the background (up to 32 queued) while the program goes on.\n- `X` substrings aren't supported; `=variable;` is.\n\nExample:\n\n```\nPLAY \"T160 O3 L8 CDEFGAB > C\"\n```\n\nSee also: [SOUND](#ref-sound), [PLAY(n)](#ref-playn), [ON PLAY](#ref-on-play)"},{"title":"PLAY ON","id":"ref-play-on","kind":"Statement","body":"*Statement* · `PLAY ON | OFF | STOP`\n\nTurns the PLAY event (ON PLAY) on, off, or holds it.\n\nSee also: [ON PLAY](#ref-on-play)"},{"title":"PLAY(n)","id":"ref-playn","kind":"Function","body":"*Function* · `PLAY(n)`\n\nHow much is still waiting in the background queue (`n` is ignored): each note counts twice, as the note and the short gap after it (MN, normal style).\n\nExample:\n\n```\nPLAY \"MB CDE\": PRINT PLAY(0)\n```\n\nShows:\n\n```\n 6\n```\n\nSee also: [PLAY](#ref-play), [ON PLAY](#ref-on-play)"},{"title":"POKE","id":"ref-poke","kind":"Statement","body":"*Statement* · `POKE offset, byte`\n\nWrites a byte to the emulated memory (DEF SEG). The text screen and BIOS bytes accept it and change nothing here.\n\nSee also: [PEEK](#ref-peek)"},{"title":"POS","id":"ref-pos","kind":"Function","body":"*Function* · `POS(n)`\n\nThe column the cursor is in, 1-80 (`n` is ignored).\n\nExample:\n\n```\nPRINT \"ABC\";: PRINT POS(0)\n```\n\nShows:\n\n```\nABC 4\n```\n\nSee also: [CSRLIN](#ref-csrlin)"},{"title":"PRINT","id":"ref-print","kind":"Statement","body":"*Statement* · `PRINT [items]`\n\nPrints numbers and strings. `;` between items prints them together, `,` jumps to the next 14-column zone; a `;` or `,` at the end keeps the cursor on the line.\n\n- Numbers print with a space before them (or a `-`) and one after.\n- `TAB(n)` and `SPC(n)` position the text.\n- Lines wrap at 80 columns.\n\nExample:\n\n```\nPRINT \"A\"; 1, \"B\"; 2\n```\n\nShows:\n\n```\nA 1           B 2\n```\n\nSee also: [PRINT USING](#ref-print-using), [WRITE](#ref-write), [TAB](#ref-tab)"},{"title":"PRINT #","id":"ref-print-1","kind":"Statement","body":"*Statement* · `PRINT #n, [USING fmt$;] items`\n\nLike PRINT, into file `n`. Lines end in CR LF (CR alone on COM1 unless LF was asked for), and there is no 80-column wrap.\n\nExample:\n\n```\nPRINT #1, \"TOTAL\"; 42\n```\n\nSee also: [WRITE #](#ref-write-1), [PRINT](#ref-print)"},{"title":"PRINT USING","id":"ref-print-using","kind":"Statement","body":"*Statement* · `PRINT USING fmt$; items[;]`\n\nPrints numbers and strings in the fields of `fmt$` (see PRINT USING formats); the format is used again from its start for more items.\n\n- Also `PRINT #n, USING`, and after other items: `PRINT \"X =\"; USING \"##.#\"; X`.\n- A number too big for its field is printed in full after a `%`.\n\nExample:\n\n```\nPRINT USING \"###.##\"; 3.14159; -2\n```\n\nShows:\n\n```\n  3.14 -2.00\n```\n\nSee also: [PRINT](#ref-print)"},{"title":"PUT","id":"ref-put","kind":"Statement","body":"*Statement* · `PUT [#]n[, record]`\n\nWrites random file `n`'s buffer as record `record` (from 1; default the one after the last).\n\nExample:\n\n```\nLSET NM$ = \"Ada\": PUT #1, 1\n```\n\nSee also: [GET](#ref-get), [FIELD](#ref-field)"},{"title":"PWM","id":"ref-pwm","kind":"Statement","body":"*Statement* · `PWM pin, freq[, duty]`\n\nRuns PWM on a pin at `freq` (8 Hz-10 MHz) with a duty of 0-100 % (default 50); `PWM pin, 0` stops it.\n\n- Pins in pairs (GP0/1, GP2/3...) share one frequency, and GP16-31 share GP0-15's slices: changing one warns about its partner.\n\nExample:\n\n```\nPWM LED, 1000, 10\n```\n\nSee also: [SERVO](#ref-servo), [PIN](#ref-pin)"},{"title":"RANDOMIZE","id":"ref-randomize","kind":"Statement","body":"*Statement* · `RANDOMIZE [seed]`\n\nStarts RND's sequence afresh: from the clock without a seed, else from `seed` (the same seed, the same numbers).\n\nExample:\n\n```\nRANDOMIZE: PRINT INT(RND * 6) + 1\n```\n\nShows:\n\n```\n 4\n```\n\nSee also: [RND](#ref-rnd)"},{"title":"READ","id":"ref-read","kind":"Statement","body":"*Statement* · `READ var[, var...]`\n\nTakes the next items from DATA lines, in order.\n\n- Errors: `Out of DATA` (4); `Syntax error` reading a string into a number.\n\nExample:\n\n```\n10 READ A, B$: PRINT A; B$\n20 DATA 5, CATS\nRUN\n```\n\nShows:\n\n```\n 5 CATS\n```\n\nSee also: [DATA](#ref-data), [RESTORE](#ref-restore)"},{"title":"REM","id":"ref-rem","kind":"Statement","body":"*Statement* · `REM text | ' text`\n\nA remark: the rest of the line is ignored. `'` is short for `:REM`.\n\nExample:\n\n```\n10 REM Setup\n20 X = 1 ' start\n```"},{"title":"RENUM","id":"ref-renum","kind":"Command","body":"*Command* · `RENUM [new][, [old][, step]]`\n\nRenumbers program lines from line `old` (default the first) as `new`, `new+step`... (default 10 and 10), and changes the line numbers after GOTO, GOSUB, THEN, ELSE, RESTORE, RESUME and RUN to match.\n\n- Not for a program without line numbers (NUMBERS ON first).\n\nExample:\n\n```\nRENUM 100, , 10\n```\n\nSee also: [AUTO](#ref-auto), [DELETE](#ref-delete)"},{"title":"RESET","id":"ref-reset","kind":"Statement","body":"*Statement* · `RESET`\n\nCloses every open file.\n\nSee also: [CLOSE](#ref-close)"},{"title":"RESTORE","id":"ref-restore","kind":"Statement","body":"*Statement* · `RESTORE [line | label]`\n\nMakes READ start again from the first DATA (or from `line` or `label`).\n\nExample:\n\n```\nRESTORE 500\n```\n\nSee also: [READ](#ref-read), [DATA](#ref-data)"},{"title":"RESUME","id":"ref-resume","kind":"Statement","body":"*Statement* · `RESUME | RESUME NEXT | RESUME line | RESUME label`\n\nEnds an error handler: `RESUME` retries the statement that failed, `RESUME NEXT` goes on after it, `RESUME line` goes to the line.\n\n- Errors: `RESUME without error` (20).\n\nExample:\n\n```\n100 PRINT \"skipped\": RESUME NEXT\n```\n\nSee also: [ON ERROR GOTO](#ref-on-error-goto)"},{"title":"RETURN","id":"ref-return","kind":"Statement","body":"*Statement* · `RETURN`\n\nReturns from a GOSUB (or an event subroutine) to the statement after the call. It also ends FOR and WHILE loops started in the subroutine.\n\n- Errors: `RETURN without GOSUB` (3).\n\nSee also: [GOSUB](#ref-gosub)"},{"title":"RIGHT$","id":"ref-right","kind":"Function","body":"*Function* · `RIGHT$(s$, n)`\n\nThe last `n` characters of `s$`.\n\nExample:\n\n```\nPRINT RIGHT$(\"HELLO\", 3)\n```\n\nShows:\n\n```\nLLO\n```\n\nSee also: [LEFT$](#ref-left)"},{"title":"RMDIR","id":"ref-rmdir","kind":"Statement","body":"*Statement* · `RMDIR path$`\n\nRemoves an empty folder.\n\n- Errors: `Path/File Access Error` (75) if it isn't empty.\n\nExample:\n\n```\nRMDIR \"GAMES\"\n```\n\nSee also: [MKDIR](#ref-mkdir)"},{"title":"RND","id":"ref-rnd","kind":"Function","body":"*Function* · `RND | RND(x)`\n\nA random number from 0 to just under 1. `RND(0)` repeats the last one; a negative `x` starts a sequence from it.\n\n- RUN always starts the same sequence: RANDOMIZE for a different one.\n\nExample:\n\n```\nPRINT INT(RND * 6) + 1\n```\n\nShows:\n\n```\n 5\n```\n\nSee also: [RANDOMIZE](#ref-randomize)"},{"title":"RSET","id":"ref-rset","kind":"Statement","body":"*Statement* · `RSET var$ = s$`\n\nLike LSET, right-aligned.\n\nExample:\n\n```\nRSET N$ = STR$(42)\n```\n\nSee also: [LSET](#ref-lset)"},{"title":"RUN","id":"ref-run","kind":"Command","body":"*Command* · `RUN [line | label] | RUN file$`\n\nRuns the program from the start (or from `line`), after clearing the variables, closing files and resetting DATA; `RUN file$` loads the file first.\n\n- Pins used by the last run are set back to inputs.\n\nExample:\n\n```\nRUN \"PRIMES\"\n```\n\nShows:\n\n```\n 168 primes below 1000\n```\n\nSee also: [LOAD](#ref-load), [CONT](#ref-cont)"},{"title":"SAVE","id":"ref-save","kind":"Command","body":"*Command* · `SAVE file$[, A]`\n\nSaves the program as plain text. `.BAS` is added if the name has no extension; `,A` is accepted (text is the only format).\n\n- `SAVE \"SD:GAME\"` saves to the SD card; `SAVE \"AUTORUN\"` makes it run at power-up.\n\nExample:\n\n```\nSAVE \"HELLO\"\n```\n\nSee also: [LOAD](#ref-load), [FILES](#ref-files)"},{"title":"SCREEN(r, c)","id":"ref-screenr-c","kind":"Function","body":"*Function* · `SCREEN(row, col[, 1])`\n\nThe character at a screen position, or with 1 its colours. A terminal can't be read back, so it gives 32 (a space), or 7.\n\nExample:\n\n```\nPRINT SCREEN(1, 1)\n```\n\nShows:\n\n```\n 32\n```\n\nSee also: [PEEK](#ref-peek)"},{"title":"SERVO","id":"ref-servo","kind":"Statement","body":"*Statement* · `SERVO pin, angle`\n\nDrives a hobby servo to `angle` 0-180 degrees (0.5-2.5 ms pulses at 50 Hz).\n\nExample:\n\n```\nSERVO 16, 90\n```\n\nSee also: [PWM](#ref-pwm)"},{"title":"SGN","id":"ref-sgn","kind":"Function","body":"*Function* · `SGN(x)`\n\n1 if `x` is positive, -1 if negative, 0 if 0.\n\nExample:\n\n```\nPRINT SGN(-7); SGN(0); SGN(3)\n```\n\nShows:\n\n```\n-1  0  1\n```\n\nSee also: [ABS](#ref-abs)"},{"title":"SHARED","id":"ref-shared","kind":"Statement","body":"*Statement* · `SHARED var[, var...]`\n\nIn a SUB or FUNCTION: these variables (arrays as `A()`) are the program's rather than the call's own.\n\n- Errors: `Illegal function call` (5) outside a SUB or FUNCTION.\n\nExample:\n\n```\nSUB COUNTUP\n  SHARED COUNT\n  COUNT = COUNT + 1\nEND SUB\n```\n\nSee also: [SUB](#ref-sub), [FUNCTION](#ref-function)"},{"title":"SIN","id":"ref-sin","kind":"Function","body":"*Function* · `SIN(x)`\n\nThe sine of `x` radians.\n\nExample:\n\n```\nPRINT SIN(3.14159 / 2)\n```\n\nShows:\n\n```\n 1\n```\n\nSee also: [COS](#ref-cos), [TAN](#ref-tan), [ATN](#ref-atn)"},{"title":"SOUND","id":"ref-sound","kind":"Statement","body":"*Statement* · `SOUND freq, ticks`\n\nA tone of `freq` Hz (37-32767; 32767 is silence) for `ticks` (18.2 make a second). After PLAY \"MB\" it joins the background queue; ticks 0 stops the sound.\n\n- Errors: `Illegal function call` (5) out of range.\n\nExample:\n\n```\nSOUND 440, 18\n```\n\nSee also: [BEEP](#ref-beep), [PLAY](#ref-play)"},{"title":"SPACE$","id":"ref-space","kind":"Function","body":"*Function* · `SPACE$(n)`\n\nA string of `n` (0-255) spaces.\n\nExample:\n\n```\nPRINT \"[\"; SPACE$(3); \"]\"\n```\n\nShows:\n\n```\n[   ]\n```\n\nSee also: [STRING$](#ref-string), [SPC](#ref-spc)"},{"title":"SPC","id":"ref-spc","kind":"Function","body":"*Function* · `SPC(n)`\n\nIn PRINT, prints `n` spaces.\n\nExample:\n\n```\nPRINT \"A\"; SPC(3); \"B\"\n```\n\nShows:\n\n```\nA   B\n```\n\nSee also: [TAB](#ref-tab), [SPACE$](#ref-space)"},{"title":"SPI","id":"ref-spi","kind":"Statement","body":"*Statement* · `SPI OPEN [sck, mosi, miso[, khz[, mode]]] | SPI WRITE item[, item...] | SPI CLOSE`\n\nThe chip's SPI. OPEN starts it (default SPI0: GP6 SCK, GP7 MOSI, GP4 MISO; 1000 kHz, 1-50000; mode 0-3), WRITE sends bytes ignoring what comes back, CLOSE frees the pins. Drive chip select yourself with PIN (GP5 is free for it).\n\n- SPI1 (GP10-15) is the SD card's while a card is in.\n- Errors: `Device unavailable` (68) before OPEN.\n\nExample:\n\n```\nPIN 5, 1: SPI OPEN: PIN 5, 0: SPI WRITE &H9F: ID$ = SPI$(STRING$(3, 0)): PIN 5, 1\n```\n\nSee also: [SPI$](#ref-spi-1), [I2C](#ref-i2c)"},{"title":"SPI$","id":"ref-spi-1","kind":"Function","body":"*Function* · `SPI$(out$)`\n\nSends the bytes of `out$` on the open SPI and returns the bytes that came back meanwhile (as many).\n\nExample:\n\n```\nR$ = SPI$(STRING$(4, 0))\n```\n\nSee also: [SPI](#ref-spi)"},{"title":"SQR","id":"ref-sqr","kind":"Function","body":"*Function* · `SQR(x)`\n\nThe square root of `x` (0 or more).\n\n- Errors: `Illegal function call` (5) for a negative `x`.\n\nExample:\n\n```\nPRINT SQR(2)\n```\n\nShows:\n\n```\n 1.41421356\n```"},{"title":"STOP","id":"ref-stop","kind":"Statement","body":"*Statement* · `STOP`\n\nStops the program with `Break in <line>`; CONT carries on. Files stay open.\n\nSee also: [END](#ref-end), [CONT](#ref-cont)"},{"title":"STR$","id":"ref-str","kind":"Function","body":"*Function* · `STR$(x)`\n\nThe number `x` as PRINT shows it, with a space before a positive number.\n\nExample:\n\n```\nPRINT \"<\"; STR$(42); \">\"\n```\n\nShows:\n\n```\n< 42>\n```\n\nSee also: [VAL](#ref-val)"},{"title":"STRING$","id":"ref-string","kind":"Function","body":"*Function* · `STRING$(n, c | c$)`\n\n`n` (0-255) copies of character code `c` or of the first character of `c$`.\n\nExample:\n\n```\nPRINT STRING$(5, \"*\"); STRING$(3, 65)\n```\n\nShows:\n\n```\n*****AAA\n```\n\nSee also: [SPACE$](#ref-space)"},{"title":"SUB","id":"ref-sub","kind":"Statement","body":"*Statement* · `SUB name[(param[, param...])] ... END SUB`\n\nA subroutine with parameters and variables of its own, called by its name: `name arg, arg` or `CALL name(arg, arg)`. EXIT SUB leaves it early.\n\n- Its variables (and arrays) are its own unless SHARED names them; the parameters are set to the arguments (by value: a copy). Up to 8 parameters; recursion works.\n- The program runs on past a SUB without running it. SUBs are found when the program starts, in its INCLUDE libraries too.\n- A name must not start with a keyword (`PRINTIT` would be PRINT).\n- Errors: `Wrong number of arguments` (86), `SUB without END SUB` (82), `END SUB without SUB` (84), `Duplicate Definition` (10).\n\nExample:\n\n```\nSUB SHOW(N$, T)\n  FOR I = 1 TO T: PRINT N$;: NEXT: PRINT\nEND SUB\nSHOW \"HI \", 3\n```\n\nShows:\n\n```\nHI HI HI\n```\n\nSee also: [FUNCTION](#ref-function), [SHARED](#ref-shared), [CALL](#ref-call), [GOSUB](#ref-gosub)"},{"title":"SWAP","id":"ref-swap","kind":"Statement","body":"*Statement* · `SWAP a, b`\n\nExchanges two variables of the same type.\n\n- Errors: `Type mismatch` (13).\n\nExample:\n\n```\nA = 1: B = 2: SWAP A, B: PRINT A; B\n```\n\nShows:\n\n```\n 2  1\n```\n\nSee also: [LET](#ref-let)"},{"title":"SYSTEM","id":"ref-system","kind":"Command","body":"*Command* · `SYSTEM`\n\nLeaves BASIC and starts it afresh, as after a reset (the files on the disks stay; AUTORUN.BAS isn't run again).\n\nSee also: [NEW](#ref-new)"},{"title":"TAB","id":"ref-tab","kind":"Function","body":"*Function* · `TAB(n)`\n\nIn PRINT, moves to column `n` (1-80); to the next line first if the cursor is already past it.\n\n- At column `n` already, it does nothing; past it, it goes to column `n` of the next line. So `PRINT T; TAB(4); \"hello\"` stays on one line for T = 5 (\" 5 \" fills columns 1-3) but not for T = 10 (\" 10 \" fills 1-4).\n- Give TAB room for the widest number (`TAB(6)` for up to 999), or a fixed width: `PRINT USING \"### \"; T;: PRINT \"hello\"`.\n\nExample:\n\n```\nPRINT \"A\"; TAB(10); \"B\"\n```\n\nShows:\n\n```\nA        B\n```\n\nSee also: [SPC](#ref-spc), [LOCATE](#ref-locate)"},{"title":"TAN","id":"ref-tan","kind":"Function","body":"*Function* · `TAN(x)`\n\nThe tangent of `x` radians.\n\nExample:\n\n```\nPRINT TAN(.7854)\n```\n\nShows:\n\n```\n 1.00000367\n```\n\nSee also: [ATN](#ref-atn)"},{"title":"TEMP","id":"ref-temp","kind":"Function","body":"*Function* · `TEMP()`\n\nThe chip's temperature in °C (uncalibrated: within a few degrees).\n\nExample:\n\n```\nPRINT INT(TEMP() * 10) / 10\n```\n\nShows:\n\n```\n 27.3\n```\n\nSee also: [ADC](#ref-adc)"},{"title":"TIME$","id":"ref-time","kind":"","body":"*Statement / function* · `TIME$ = \"hh:mm:ss\" | TIME$ = \"h:mm[:ss] AM|PM\" | TIME$`\n\nSets the time of day, or gives it as \"hh:mm:ss\" (24-hour, in the time zone `TZ` in CONFIG.TXT; UTC without it).\n\n- With `CLOCK = 12` in CONFIG.TXT it gives \"hh:mm:ss AM\" or \"PM\" (11 characters).\n- Setting takes 24-hour time or 12-hour with AM/PM, whatever CLOCK says.\n- Wi-Fi builds set the clock by NTP.\n\nExample:\n\n```\nTIME$ = \"09:30:00\": PRINT TIME$\n```\n\nShows:\n\n```\n09:30:00\n```\n\nSee also: [DATE$](#ref-date), [TIMER](#ref-timer)"},{"title":"TIMER","id":"ref-timer","kind":"Function","body":"*Function* · `TIMER`\n\nSeconds since the board started, with fractions: for timing things.\n\nExample:\n\n```\nT = TIMER: PAUSE 500: PRINT TIMER - T\n```\n\nShows:\n\n```\n .500118999\n```\n\nSee also: [PAUSE](#ref-pause), [ON TIMER](#ref-on-timer)"},{"title":"TIMER ON","id":"ref-timer-on","kind":"Statement","body":"*Statement* · `TIMER ON | OFF | STOP`\n\nTurns the timer event (ON TIMER) on, off, or holds it.\n\nSee also: [ON TIMER](#ref-on-timer)"},{"title":"TROFF","id":"ref-troff","kind":"Command","body":"*Command* · `TROFF`\n\nTurns line tracing off.\n\nSee also: [TRON](#ref-tron)"},{"title":"TRON","id":"ref-tron","kind":"Command","body":"*Command* · `TRON`\n\nTurns line tracing on: each line's number is printed in brackets as it runs.\n\nExample:\n\n```\nTRON: RUN\n```\n\nShows:\n\n```\n[10][20][10][20]...\n```\n\nSee also: [TROFF](#ref-troff)"},{"title":"UCASE$","id":"ref-ucase","kind":"Function","body":"*Function* · `UCASE$(s$)`\n\n`s$` in upper case.\n\nExample:\n\n```\nPRINT UCASE$(\"Hello\")\n```\n\nShows:\n\n```\nHELLO\n```\n\nSee also: [LCASE$](#ref-lcase)"},{"title":"VAL","id":"ref-val","kind":"Function","body":"*Function* · `VAL(s$)`\n\nThe number at the start of `s$` (spaces skipped; `&H` hex and `&O` octal too); 0 if there isn't one.\n\nExample:\n\n```\nPRINT VAL(\"12.5KG\"); VAL(\"&HFF\"); VAL(\"X\")\n```\n\nShows:\n\n```\n 12.5  255  0\n```\n\nSee also: [STR$](#ref-str)"},{"title":"VIEW PRINT","id":"ref-view-print","kind":"Statement","body":"*Statement* · `VIEW PRINT [top TO bottom]`\n\nMakes only rows `top` to `bottom` scroll (an ANSI scroll region); `VIEW PRINT` alone undoes it.\n\nExample:\n\n```\nVIEW PRINT 5 TO 20\n```\n\nSee also: [LOCATE](#ref-locate), [CLS](#ref-cls)"},{"title":"WATCHDOG","id":"ref-watchdog","kind":"Statement","body":"*Statement* · `WATCHDOG ms | WATCHDOG FEED | WATCHDOG OFF | WATCHDOG`\n\nThe chip's watchdog: `WATCHDOG ms` arms it, and the board resets unless `WATCHDOG FEED` comes within `ms` milliseconds (100 up to 8388 on the RP2040, 16777 on the RP2350); `WATCHDOG OFF` disarms it; `WATCHDOG` alone says how it is.\n\n- A break (Ctrl-C or STOP) turns it off, as someone is there; an error or END leaves it on, so a board on its own resets and runs AUTORUN.BAS again.\n- Disk reads and writes, XMODEM, Wi-Fi waits and the full-screen editor feed it themselves; INPUT and PAUSE don't, so a program waiting longer than `ms` resets the board.\n- `WATCHDOG = ms` in CONFIG.TXT arms it just before AUTORUN.BAS runs.\n- Errors: `Illegal function call` (5) for a time out of range.\n\nExample:\n\n```\nWATCHDOG 2000: PAUSE 500: WATCHDOG FEED: WATCHDOG OFF: PRINT \"OK\"\n```\n\nShows:\n\n```\nOK\n```\n\nSee also: [WDRESET](#ref-wdreset)"},{"title":"WDRESET","id":"ref-wdreset","kind":"Function","body":"*Function* · `WDRESET`\n\n-1 (true) if the last reset was the watchdog's (it ran out), else 0.\n\n- The banner says `Reset by the watchdog` then too.\n\nExample:\n\n```\nIF WDRESET THEN PRINT \"Restarted by the watchdog\"\n```\n\nSee also: [WATCHDOG](#ref-watchdog)"},{"title":"WEND","id":"ref-wend","kind":"Statement","body":"*Statement* · `WEND`\n\nEnds a WHILE loop.\n\n- Errors: `WEND without WHILE` (30).\n\nSee also: [WHILE](#ref-while)"},{"title":"WHILE","id":"ref-while","kind":"Statement","body":"*Statement* · `WHILE cond ... WEND`\n\nRepeats the lines up to WEND while `cond` is true (not 0); tested before each pass.\n\n- Up to 32 nested.\n- Errors: `WHILE without WEND` (29).\n\nExample:\n\n```\nI = 1: WHILE I < 100: I = I * 2: WEND: PRINT I\n```\n\nShows:\n\n```\n 128\n```\n\nSee also: [FOR](#ref-for), [IF](#ref-if)"},{"title":"WIDTH","id":"ref-width","kind":"Statement","body":"*Statement* · `WIDTH n`\n\nAccepted for old programs; the screen stays 80 columns."},{"title":"WIFI","id":"ref-wifi","kind":"Command","body":"*Command* · `WIFI | WIFI ON | WIFI OFF | WIFI SCAN`\n\nWi-Fi (on a Pico 2 W, a Pico W, or a Pico Plus 2 with an RM2 breakout): `WIFI` shows the connection (the network, the signal, the IP address) and the clock; `WIFI ON` connects to CONFIG.TXT's network (again), `WIFI OFF` leaves it; `WIFI SCAN` lists the networks around.\n\n- At power-up BASIC connects in the background to `WIFI_SSID` (with `WIFI_PASSWORD`) from FLASH:/CONFIG.TXT, tries again every 30 seconds when the network is lost, and sets the clock by NTP once it's up, then every hour; DATE$ and TIME$ give the local time (`TZ`).\n- Builds without Wi-Fi say `Feature not available` (73).\n\nExample:\n\n```\nWIFI\n```\n\nShows:\n\n```\nConnected to HOME, signal -52 dBm\nIP 192.168.1.20, gateway 192.168.1.1, DNS 192.168.1.1\nClock: 2026-10-31 18:30:05 EDT, from pool.ntp.org at 2026-10-31 18:29:58 EDT\n```\n\nSee also: [NTP](#ref-ntp), [CONFIG](#ref-config), [TIME$](#ref-time)"},{"title":"WIFI()","id":"ref-wifi-1","kind":"Function","body":"*Function* · `WIFI(n) | WIFI$(n)`\n\nWi-Fi's state for a program: `WIFI(0)` is -1 (true) while connected with an IP address, else 0; `WIFI(1)` the signal in dBm; `WIFI(2)` -1 once NTP has set the clock; `WIFI(3)` the link's state (1 joining, 2 waiting for an address, 3 up, 0 down, -1 failed, -2 no such network, -3 wrong password). `WIFI$(0)` is the IP address, `WIFI$(1)` the network's name.\n\n- Builds without Wi-Fi give 0 and \"\" (so a program runs on any board).\n\nExample:\n\n```\nIF WIFI(0) THEN PRINT \"Online at \"; WIFI$(0) ELSE PRINT \"Offline\"\n```\n\nShows:\n\n```\nOnline at 192.168.1.215\n```\n\nSee also: [WIFI](#ref-wifi), [NTP](#ref-ntp)"},{"title":"WRITE","id":"ref-write","kind":"Statement","body":"*Statement* · `WRITE [items]`\n\nPrints the items separated by commas, strings in quotes, numbers without spaces: what INPUT # reads back exactly.\n\nExample:\n\n```\nWRITE \"Ann\", 120\n```\n\nShows:\n\n```\n\"Ann\",120\n```\n\nSee also: [WRITE #](#ref-write-1), [PRINT](#ref-print)"},{"title":"WRITE #","id":"ref-write-1","kind":"Statement","body":"*Statement* · `WRITE #n, items`\n\nWrites the items to file `n` separated by commas, strings in quotes: INPUT # reads them back exactly.\n\nExample:\n\n```\nWRITE #1, \"Ann\", 120\n```\n\nSee also: [INPUT #](#ref-input-1)"},{"title":"XOR","id":"ref-xor","kind":"Operator","body":"*Operator* · `a XOR b`\n\nBitwise exclusive OR: true if just one is.\n\nExample:\n\n```\nPRINT 12 XOR 10\n```\n\nShows:\n\n```\n 6\n```\n\nSee also: [OR](#ref-or)"},{"title":"XRECV","id":"ref-xrecv","kind":"Statement","body":"*Statement* · `XRECV file$[, protocol$]`\n\nReceives a file from the terminal by XMODEM and saves it as `file$`, replacing one of that name. Start the terminal's XMODEM send within a minute.\n\n- CRC-16 or checksum; 128- or 1K-byte blocks. XMODEM's ^Z padding is taken off the end.\n- `protocol$` `\"Y\"` takes YMODEM and `\"Z\"` ZMODEM instead (`\"X\"`, XMODEM, is the default). They send the file's size, so a file that ends in ^Z bytes keeps them; the file is still saved as `file$`, whatever the sender calls it.\n- A failed transfer deletes the partial file and gives `Device I/O error` (57). Ctrl-X a few times cancels.\n- Works to either drive: `XRECV \"SD:PIC.BMP\"`.\n\nExample:\n\n```\nXRECV \"GAME.BAS\"\n```\n\nShows:\n\n```\nStart the XMODEM send on the terminal now.\nReceived 1 file, 2048 bytes.\n```\n\nSee also: [XSEND](#ref-xsend), [LOAD](#ref-load)"},{"title":"XSEND","id":"ref-xsend","kind":"Statement","body":"*Statement* · `XSEND file$[, protocol$]`\n\nSends a file to the terminal by XMODEM (1K blocks with CRC-16, or 128-byte ones with a checksum if the receiver asks).\n\n- `protocol$` `\"Y\"` sends by YMODEM (the name and size go first) and `\"Z\"` by ZMODEM; `\"X\"` is the default.\n- Errors: `Device I/O error` (57) if it fails or the file can't be read.\n\nExample:\n\n```\nXSEND \"GAME.BAS\"\n```\n\nShows:\n\n```\nStart the XMODEM receive on the terminal now.\nSent 1 file, 2048 bytes.\n```\n\nSee also: [XRECV](#ref-xrecv)"},{"title":"\\ and MOD","id":"ref-and-mod","kind":"Operator","body":"*Operator* · `a \\ b, a MOD b`\n\nInteger division (both rounded to whole numbers first, the result cut towards 0) and its remainder.\n\nExample:\n\n```\nPRINT 17 \\ 5; 17 MOD 5\n```\n\nShows:\n\n```\n 3  2\n```\n\nSee also: [+ - * / ^](#ref--)\n\n## Appendix A: error codes\n\n| Code | Message | Code | Message |\n|---|---|---|---|\n| 1 | NEXT without FOR | 26 | FOR without NEXT |\n| 2 | Syntax error | 29 | WHILE without WEND |\n| 3 | RETURN without GOSUB | 30 | WEND without WHILE |\n| 4 | Out of DATA | 50 | FIELD overflow |\n| 5 | Illegal function call | 52 | Bad file number |\n| 6 | Overflow | 53 | File not found |\n| 7 | Out of memory | 54 | Bad file mode |\n| 8 | Undefined line number | 55 | File already open |\n| 9 | Subscript out of range | 57 | Device I/O error |\n| 10 | Duplicate Definition | 58 | File already exists |\n| 11 | Division by zero | 61 | Disk full |\n| 12 | Illegal direct | 62 | Input past end |\n| 13 | Type mismatch | 63 | Bad record number |\n| 15 | String too long | 64 | Bad file name |\n| 17 | Can't continue | 67 | Too many files |\n| 18 | Undefined user function | 68 | Device unavailable |\n| 19 | No RESUME | 70 | Permission denied |\n| 20 | RESUME without error | 71 | Disk not ready |\n| 22 | Missing operand | 73 | Feature not available |\n| 24 | Device Timeout | 75 | Path/File Access Error |\n| 25 | Device Fault | 76 | Path not found |\n\n(Other codes, 14, 16, 23, 27, 51, 66, 69, 72 and 74, have their messages for ERROR n; unknown codes print `Unprintable error`.)\n\n## Appendix B: PRINT USING formats\n\n| Field | Meaning |\n|---|---|\n| `#` | a digit position |\n| `.` | the decimal point |\n| `,` before the point | commas between thousands |\n| `+` first or last | always show the sign there |\n| `-` last | a minus after negative numbers |\n| `**` | fill the space before the number with `*` |\n| `$$` | a `$` just before the number (`**$` does both) |\n| `^^^^` | exponent form (`##.##^^^^` prints ` 2.35E+02`) |\n| `!` | the first character of a string |\n| `\\  \\` | the first n + 2 characters of a string |\n| `&` | the whole string |\n| `_` | prints the next character as it is |\n\n## Appendix C: INKEY$ key codes\n\nOrdinary keys give their character. These give CHR$(0) followed by the PC scan code:\n\n| Key | Code | Key | Code |\n|---|---|---|---|\n| Up | 72 | Home | 71 |\n| Down | 80 | End | 79 |\n| Left | 75 | PgUp | 73 |\n| Right | 77 | PgDn | 81 |\n| F1-F10 | 59-68 | Ins | 82 |\n| | | Del | 83 |\n\nEsc gives CHR$(27), Enter CHR$(13), Backspace CHR$(8), Tab CHR$(9), Ctrl-A to Ctrl-Z CHR$(1)-CHR$(26) (Ctrl-C stops the program).\n\n## Appendix D: characters\n\nBASIC uses the IBM PC character set (code page 437) and sends each character to the terminal as its Unicode picture in UTF-8: CHR$(1) ☺, CHR$(3) ♥, CHR$(176)-CHR$(178) ░▒▓, CHR$(179) │, CHR$(196) ─, CHR$(218) ┌, CHR$(219) █, CHR$(227) π, CHR$(248) °. Control codes print their pictures too, except 7 (beep), 8 (backspace), 9 (tab), 10 (line feed), 12 (clear screen), 13 (carriage return) and 27 (Esc, for ANSI codes); 11 moves the cursor home and 28-31 move it right, left, up and down.\n\n## Appendix E: pins BASIC uses\n\n| Pin | Used by | Boards |\n|---|---|---|\n| GP18 | the speaker (BEEP, SOUND, PLAY) | all (the Maker Pi Pico's buzzer) |\n| GP10-15 | the SD card, while one is in | all (the Maker Pi Pico's slot) |\n| GP47 | the PSRAM | Pico Plus 2 |\n| GP28 | NEOPIXEL's default (the Maker Pi Pico's RGB LED) | while open |\n| GP20 | held low at power-up: skip AUTORUN.BAS | all (the Maker Pi Pico's first button) |\n| GP2/3, GP4-7, GP8/9 | I2C, SPI and COM1's defaults | while open |\n\nThe console is the board's USB port, so GP0 and GP1 are free. PINS lists what each pin is doing."}]};
